// Üretilen dosya: tool/ozgun/uret.py. Müzik · Türk sanat müziği besteciler ve formlar (orta).
const ozMusic10Orta = <(String, String, List<String>, String)>[
  ('Neva ile hüseyni perdeleri arasında yer alan ve adını taşıyan bir makamın da bulunduğu ara perde hangisidir?', 'Hisar', ['Zirgüle', 'Eviç', 'Kürdi'], 'Neva (re) ile hüseyni (mi) arasındaki ara perdeler nim hisar, hisar ve dik hisardır. Zirgüle rast ile dügâh, kürdi dügâh ile segâh arasındadır.'),
  ('Rast ile dügâh perdeleri arasında kalan ve Hicaz ailesinin bir makamına da adını veren ara perde hangisidir?', 'Zirgüle', ['Hisar', 'Nim hicaz', 'Dik acem'], 'Rast (sol) ile dügâh (la) arasında nim zirgüle, zirgüle ve dik zirgüle perdeleri bulunur.'),
  ('Kaba bölgede \'mi\' sesine karşılık gelen ve hüseyni perdesinin bir oktav pesti olan perde hangisidir?', 'Hüseyniaşiran', ['Acemaşiran', 'Irak', 'Yegâh'], '\'Aşiran\' eki kaba bölgeyi gösterir; hüseyninin (mi) bir oktav pesti hüseyniaşirandır.'),
  ('Rast dörtlüsü sırasıyla tanini, büyük mücenneb ve küçük mücenneb aralıklarından oluşur. Bu dörtlüde birinci perde ile üçüncü perde arası kaç komadır?', '17', ['13', '18', '170'], 'Tanini 9 koma, büyük mücenneb 8 komadır; 9 + 8 = 17 koma eder.'),
  ('Çargâh dörtlüsü tanini, tanini, bakiye aralıklarından oluşur. Bu dörtlü Batı müziğindeki hangi dizinin ilk dört sesine aralık bakımından denk düşer?', 'Majör dizinin', ['Doğal minör dizinin', 'Frigyen dizinin', 'Armonik minör dizinin'], 'Tam ton, tam ton, yarım ton düzeni majör dizinin ilk dört sesidir (do-re-mi-fa).'),
  ('Bir dörtlünün aralıkları sırasıyla küçük mücenneb, artık ikili ve küçük mücenneb ise bu dörtlü hangi cinstir?', 'Hicaz dörtlüsü', ['Uşşak dörtlüsü', 'Rast dörtlüsü', 'Kürdi dörtlüsü'], 'Ortadaki geniş artık ikili aralığı, iki yanında dar aralıklarla Hicaz dörtlüsünü tanımlar.'),
  ('Karcığar makamında güçlü görevi yapan perde hangisidir?', 'Neva', ['Hüseyni', 'Çargâh', 'Segâh'], 'Karcığar dizisi dügâhta Uşşak dörtlüsü ile nevada Hicaz beşlisinden oluşur; iki parçanın birleştiği neva güçlüdür.'),
  ('Uzzal makamının güçlüsü hangi perdedir?', 'Hüseyni', ['Neva', 'Çargâh', 'Eviç'], 'Uzzal dügâhta Hicaz beşlisi ile hüseynide Uşşak dörtlüsünden oluşur; beşli hüseynide bittiği için güçlü hüseynidir.'),
  ('Hümayun makamında dizinin iki parçasının birleştiği ve güçlü olarak kullanılan perde hangisidir?', 'Neva', ['Hüseyni', 'Hicaz', 'Gerdaniye'], 'Hümayun dügâhta Hicaz dörtlüsü ile nevada Buselik beşlisinden oluşur; güçlü nevadır.'),
  ('Kürdi makamının güçlüsü hangi perdedir?', 'Neva', ['Hüseyni', 'Kürdi', 'Çargâh'], 'Kürdi makamı dügâhta Kürdi dörtlüsü ile nevada Buselik beşlisinden oluşur; güçlü nevadır.'),
  ('Bayati makamının güçlüsü hangi perdedir?', 'Neva', ['Hüseyni', 'Segâh', 'Dügâh'], 'Bayati, Uşşak ile aynı diziyi kullanır; dügâhtaki Uşşak dörtlüsü ile nevadaki Buselik beşlisinin birleştiği neva güçlüdür.'),
  ('Hüzzam makamının durağı hangi perdedir?', 'Segâh', ['Dügâh', 'Rast', 'Irak'], 'Hüzzam, Segâh makamı gibi segâh perdesinde karar veren birleşik bir makamdır.'),
  ('Nihavend makamında güçlü olarak kullanılan perde hangisidir?', 'Neva', ['Dügâh', 'Hüseyni', 'Gerdaniye'], 'Nihavend rastta Buselik beşlisi ile nevada Kürdi ya da Hicaz dörtlüsünden oluşur; güçlü nevadır.'),
  ('Uşşak makamının donanımında yalnız tek bir işaret bulunur. Bu işaret hangi perdeyi gösterir?', 'Segâh', ['Kürdi', 'Eviç', 'Hicaz'], 'Uşşak dizisinde değiştirici işaret gerektiren tek perde segâhtır; donanıma si koma bemolü konur.'),
  ('Güftesinde makam adlarının geçtiği ve her makam adı söylendiğinde ezginin o makama geçtiği kâr türüne ne ad verilir?', 'Kâr-ı natık', ['Kârçe', 'Nakış beste', 'Beste-i kadim'], 'Kâr-ı natık \'konuşan kâr\' demektir; güftede adı anılan makama müzik de geçki yapar.'),
  ('Klasik beste formunda güfte genellikle dört mısradan oluşur. Bu dört hanenin hangisi çoğunlukla farklı bir ezgiyle, meyan olarak bestelenir?', 'Üçüncü hane', ['Birinci hane', 'İkinci hane', 'Dördüncü hane'], 'Bestede birinci, ikinci ve dördüncü haneler aynı ezgiyle okunur; üçüncü hane meyan karakterindedir.'),
  ('Dört mısralı bir şarkı güftesinde dördüncü mısranın ezgisi ikinci mısranın ezgisiyle aynıdır. Bu durum şarkı formunun hangi özelliğini yansıtır?', 'Nakaratın meyandan sonra tekrarlanmasını', ['Meyanın geçki içermesini', 'Zeminin terennümle başlayıp bitmesini', 'Usulün eser içinde birkaç kez değişmesini'], 'Klasik şarkıda ikinci mısra nakarattır ve meyandan sonra gelen dördüncü mısra aynı ezgiyle okunur.'),
  ('Şarkı formunun yaygınlaşıp klasik fasılda kâr ve bestenin yerini almaya başladığı dönem hangisidir?', '19. yüzyıl', ['15. yüzyıl', '16. yüzyıl', '17. yüzyıl'], '19. yüzyılda Hacı Arif Bey ve Şevki Bey gibi bestecilerle şarkı, en çok bestelenen ve dinlenen form oldu.'),
  ('Bir saz eserinin dört hanesi var; ilk üçü 10 zamanlı, sonuncusu 6 zamanlı bir usulle yazılmış ve her haneden sonra aynı teslim çalınıyor. Bu eser hangi formdadır?', 'Saz semaisi', ['Peşrev', 'Longa', 'Sirto'], 'Aksak semai (10) ile başlayıp dördüncü hanede Yürük semai (6) gibi farklı bir usule geçen dört haneli eser saz semaisidir.'),
  ('Longa formu en çok hangi ölçü yapısıyla ve nasıl bir temposuyla bilinir?', 'İki zamanlı, çok hızlı', ['Dokuz zamanlı, ağır yürüyüşlü', 'Usulsüz ve serbest', 'On zamanlı, ağır'], 'Longalar çoğunlukla 2/4 ölçüsünde, çok hareketli ve virtüözlük gösteren saz eserleridir.'),
  ('Sirto adlı hareketli saz eserlerinin adı ve kökeni hangi topluluğun dans geleneğiyle ilişkilendirilir?', 'Rum dans geleneğiyle', ['Arap bedevi geleneğiyle', 'Kafkas dans geleneğiyle', 'Mevlevi sema geleneğiyle'], 'Sirto, Rumların \'syrtos\' adlı halk dansından adını alır ve 2/4 ölçüsünde hareketli bir saz eseridir.'),
  ('Bir fasıl heyeti, ağır eserlerden sonra programın sonuna hızlı ve virtüözlük isteyen bir saz eseri koymak istiyor. Seçeneklerden hangisi bu amaca en uygundur?', 'Longa', ['Kâr', 'Ağır semai', 'Beste'], 'Longa hızlı tempolu bir saz eseridir; öteki seçenekler ağır sözlü formlardır.'),
  ('Bir şarkının sözlü bölümleri arasında yalnız sazlarla çalınan ve çoğunlukla eserin girişinde de duyulan kısa ezgilerin dinleyiciye sağladığı başlıca katkı nedir?', 'Hanendeye soluk aldırıp bölümleri birbirine bağlaması', ['Makamı değiştirip esere sürekli geçki katması', 'Usulü yavaşlatıp eseri ağırlaştırması', 'Güftenin anlamını açıklaması'], 'Aranağmeler sözlü bölümler arasında köprü kurar ve okuyucuya kısa bir dinlenme sağlar.'),
  ('Şarkılarda kullanılan Sengin semai usulü kaç zamanlıdır?', '6', ['3', '5', '10'], 'Sengin semai 6 zamanlıdır ve 6/4 olarak yazılır; Yürük semai ile aynı zaman sayısındadır ama daha ağırdır.'),
  ('Raks aksağı usulü hangi tür eserlerde en çok kullanılır?', 'Oyun havalarında ve dans ezgilerinde', ['Mevlevi ayinlerinin ilk selamında', 'Kâr formunun terennüm bölümlerinde', 'Cami musikisinde ezan okunurken'], 'Raks aksağı 9 zamanlı, adından da anlaşılacağı gibi dans (raks) ezgilerine uygun hareketli bir usuldür.'),
  ('Raks aksağı ile Aksak usulünün ortak özelliği nedir?', 'İkisinin de 9 zamanlı olması', ['İkisinin de 10 zamanlı olması', 'İkisinin de yalnız ayinlerde kullanılması', 'İkisinin de büyük usul sayılması'], 'Her iki usul de 9 zamanlıdır; vuruş düzenleri ve kullanım alanları farklıdır.'),
  ('Bir bestenin her hanesi Hafif usulünün (32 zaman) bir devrinden, her terennümü de aynı usulün yarım devrinden oluşuyor. Dört hane ve dört terennüm toplam kaç zamandır?', '192', ['160', '224', '1920'], 'Hane: 4 x 32 = 128; terennüm: 4 x 16 = 64; toplam 192 zaman.'),
  ('Aşağıdaki usullerden hangisi büyük usuller arasında yer alır?', 'Çifte düyek', ['Frenkçin', 'Devr-i hindi', 'Curcuna'], 'Çifte düyek 16 zamanlıdır ve büyük usul sınırına girer; öteki üçü küçük usuldür.'),
  ('Bir usulün vuruşlarında \'düm\' ile \'tek\' arasındaki temel ayrım neye dayanır?', 'Vuruşun kuvvetine ve sesin kalınlığına', ['Vuruşun hangi elle yapıldığına', 'Vuruşun makamın güçlüsüne denk gelmesine', 'Vuruşun sözlü bölümde olmasına'], 'Düm kuvvetli ve kalın, tek ise daha hafif ve ince sesli vuruştur; usulün ağırlık düzenini bunlar belirler.'),
  ('Kudüm çalınırken düm ve tek vuruşlarının iki ayrı kâseye vurularak verilmesi neden kolaylık sağlar?', 'Kâselerin biri kalın, öteki ince ses verdiği için', ['İki kâse aynı yükseklikte ses verdiği için', 'Kâseler makamın perdelerini verdiği için', 'Kâselerden biri yalnız terennümde çalındığı için'], 'Kudümün büyük kâsesi kalın (düm), küçük kâsesi ince (tek) ses verir; böylece usulün vuruş ayrımı duyulur.'),
  ('Şarkılarda yaygın olan 7 zamanlı Devr-i hindi ile ilahi ve ayinlerde görülen 14 zamanlı Devr-i revan arasındaki sayısal ilişki nedir?', 'Devr-i revan, Devr-i hindinin iki katı zamandır', ['İkisi aynı zaman sayısındadır', 'Devr-i hindi, Devr-i revanın iki katı zamandır', 'Aralarında sayısal bir ilişki yoktur'], '7 x 2 = 14; Devr-i revan, Devr-i hindinin iki katı zaman sayısına sahiptir.'),
  ('Büyük usullerle yazılmış bir eseri öğrenen bir hanendenin usulü tutarken en çok zorlandığı nokta genellikle nedir?', 'Uzun devir boyunca vuruşların yerini akılda tutmak', ['Makamın durağını bulmak', 'Perdeleri tanburda doğru basmak', 'Güftenin aruz veznini her mısrada değiştirmek'], 'Büyük usullerde bir devir onlarca zaman sürer; düm ve tek vuruşlarının sırası uzun bir döngü içinde izlenmelidir.'),
  ('Abdülkadir Meragi, Farabi ve Urmevi gibi isimlerin eserleri Osmanlı öncesi ve erken Osmanlı musikisini anlamada neden önemlidir?', 'Dönemin makam ve usul kuramını yazılı olarak bıraktıkları için', ['Eserlerinin ses kayıtları günümüze ulaştığı için', 'Batı notasıyla yüzlerce eser yazdıkları için', 'Mevlevi ayinlerinin tamamını besteledikleri için'], 'Bu kuramcılar edvar türü kitaplarla perde, makam ve usul bilgisini yazıya geçirmiştir; o dönemin ses kaydı ya da yaygın notası yoktur.'),
  ('Mecmua-i Saz ü Söz\'ü derleyen Ali Ufki aslen hangi ülkeden gelip Osmanlı sarayında yetişmiştir?', 'Polonya', ['Macaristan', 'Venedik', 'Boğdan'], 'Asıl adı Wojciech Bobowski olan Ali Ufki, Polonya doğumludur ve saray hizmetinde musikişinas olarak yetişmiştir.'),
  ('Ali Ufki\'nin derlemesinin bugün 17. yüzyıl Osmanlı musikisi için değerli bir kaynak olmasının başlıca nedeni nedir?', 'Eserleri ezgileriyle birlikte yazıya geçirmesi', ['Yalnız güfteleri toplaması', 'Eserlerin ses kaydını yapması', 'Makamların aralıklarını matematiksel olarak hesaplaması'], 'Dönemin güfte mecmuaları çoğunlukla yalnız sözleri verirken Ali Ufki ezgileri de notaya almıştır.'),
  ('Itri\'nin musiki yanında divan şiiri de yazdığı bilinir. Bu bilgi onun eserleri için neyi açıklar?', 'Güfte seçiminde edebî birikimi olduğunu', ['Eserlerini Batı notasıyla kendisinin yazdığını', 'Yalnız saz eseri bestelediğini', 'Şiirlerini usulsüz okuttuğunu'], 'Hem şair hem bestekâr olan Itri, sözlü eserlerinde güfteyle ezgiyi uyumlu biçimde işleyebilmiştir.'),
  ('Itri\'nin eserlerinin pek azının bugüne ulaşmış olmasının en olası nedeni hangisidir?', 'Eserlerin yazıya değil meşke dayanarak aktarılması', ['Eserlerinin yasaklanması', 'Bestelerini yalnız Avrupa\'da yayımlatmış olması', 'Bestelerini kendisinin yok etmesi'], 'Notanın yaygın olmadığı bir dönemde meşk zinciri kopan eserler unutulmuştur; Itri\'nin bestelediği eserlerin ancak küçük bir bölümü kalmıştır.'),
  ('Kantemiroğlu musiki dışında hangi alandaki eseriyle Avrupa\'da tanınmıştır?', 'Osmanlı Devleti\'nin yükseliş ve çöküş tarihi', ['İstanbul\'un camilerini anlatan mimari tarih', 'Arapça dil bilgisi', 'Gök bilimi tabloları'], 'Kantemiroğlu\'nun Osmanlı tarihini anlatan eseri Avrupa dillerine çevrilmiş ve uzun süre başvuru kaynağı olmuştur.'),
  ('Kantemiroğlu\'nun icracı olarak en çok ustalığını gösterdiği çalgı hangisidir?', 'Tanbur', ['Ney', 'Kanun', 'Kemençe'], 'Kantemiroğlu iyi bir tanburî idi ve peşrevlerinin çoğunu bu çalgının bilgisine dayanarak kaydetti.'),
  ('Kantemiroğlu\'nun derlemesinde en çok hangi tür eserler yer alır?', 'Peşrev ve saz semaileri', ['Şarkılar ve kantolar', 'Mevlevi ayinleri', 'Ezan, salâ ve temcid gibi okumalar'], 'Kantemiroğlu\'nun koleksiyonu ağırlıklı olarak dönemin saz eserlerinden, yani peşrev ve saz semailerinden oluşur.'),
  ('Galata Mevlevihanesi\'nin şeyhi olan ve Miraç gecesinin anlatıldığı büyük dinî eser \'Mi\'râciyye\'yi besteleyen musikişinas kimdir?', 'Kutbünnayi Osman Dede', ['Itri', 'Dede Efendi', 'Hafız Mehmed Zekai Dede'], 'Neyzenliğiyle \'Kutbünnayi\' (neyzenlerin kutbu) unvanını alan Osman Dede, Mi\'râciyye\'nin bestecisidir.'),
  ('Hem padişah hem bestekâr olan ve \'Adli\' mahlasıyla şiirler yazan Osmanlı hükümdarı hangisidir?', 'II. Mahmud', ['III. Selim', 'Abdülaziz', 'Kanuni Sultan Süleyman'], 'II. Mahmud, \'Adli\' mahlasını kullanan ve bestekârlığı da bulunan padişahtır.'),
  ('III. Selim döneminin Osmanlı musikisi için önemini en iyi hangisi açıklar?', 'Padişahın himayesiyle bestecilerin yetişmesi ve nota denemelerinin yapılması', ['Musikinin saraydan tamamen uzaklaştırılması', 'Mehterin kaldırılıp yerine Batı tarzı bando kurulması', 'Şarkı formunun yasaklanması'], 'III. Selim döneminde Dede Efendi gibi besteciler yetişmiş, Hamparsum ve Nasır Dede nota sistemleri geliştirmiştir.'),
  ('Mevlevilikte 1001 günlük hizmet sürecini, yani çileyi tamamlayan kişiye verilen ve İsmail Efendi\'nin adına da eklenen unvan hangisidir?', 'Dede', ['Şeyh', 'Çelebi', 'Ağa'], 'Çilesini dolduran Mevlevi \'dede\' unvanı alır; Hammamizade İsmail Efendi de bu yüzden \'Dede Efendi\' diye anılır.'),
  ('Dede Efendi ile Itri\'yi karşılaştıran bir öğrenci aşağıdaki yargılardan hangisini doğru olarak yazabilir?', 'İkisinin de hem dinî hem dindışı eser bestelemiş olduğunu', ['İkisinin de aynı padişah döneminde sarayda yaşadığını', 'İkisinin de yalnız şarkı formunda bestelediğini', 'İkisinin de 20. yüzyılda plak doldurduğunu'], 'Itri (17. yy) ve Dede Efendi (18-19. yy) farklı dönemlerde yaşamış; ikisi de tekbir, na\'t, ayin gibi dinî eserlerle birlikte dindışı eserler de bestelemiştir.'),
  ('Zekai Dede\'nin bestecilik anlayışı en iyi hangisiyle tanımlanır?', 'Klasik geleneği sürdüren ağır eserler', ['Batı armonisine dayalı eserler', 'Kanto ve operet besteleri', 'Halk türkülerinin çok sesli düzenlemeleri'], '19. yüzyılda şarkının yaygınlaştığı bir dönemde Zekai Dede beste, kâr ve ayin gibi ağır formlarda klasik çizgiyi sürdürmüştür.'),
  ('Şarkı formunda çok verimli olan Şevki Bey\'in musiki hocası olarak bilinen besteci kimdir?', 'Hacı Arif Bey', ['Dede Efendi', 'Itri', 'Tanburi Cemil Bey'], 'Şevki Bey, Hacı Arif Bey\'den meşk etmiş; ikisi şarkı formunun en verimli bestecileri arasında anılır.'),
  ('Hacı Arif Bey musiki çalışmalarında hangi padişahın himayesini görerek saraya alınmıştır?', 'Abdülmecid', ['III. Selim', 'IV. Mehmed', 'II. Abdülhamid'], 'Güzel sesi fark edilen Arif Bey, Sultan Abdülmecid\'in ilgisiyle saray musikisine girmiştir.'),
  ('Hacı Arif Bey ve Şevki Bey gibi bestecilerin yüzlerce şarkı bestelemesi 19. yüzyıl musiki hayatı hakkında neyi gösterir?', 'Dinleyicinin kısa ve hafif formlara yöneldiğini', ['Mevlevi ayinlerinin yasaklandığını', 'Klasik fasılda saz eserinin hiç kalmadığını', 'Makam kavramının terk edildiğini'], 'Şarkıların sayıca artması, toplumun kâr ve beste gibi ağır formlardan daha kısa ve kolay öğrenilen eserlere yöneldiğini gösterir.'),
  ('Dellalzade İsmail Efendi\'nin besteci olarak Dede Efendi\'den sonraki dönemde taşıdığı önem nedir?', 'Klasik formları Dede Efendi çizgisinde sürdürmesi', ['Türk müziğine çok seslilik getirmesi', 'İlk Türk operasını bestelemesi', 'Mehteri yeniden kurup başına geçmesi'], 'Dede Efendi\'nin öğrencisi olan Dellalzade, beste ve semai gibi klasik formlarda hocasının geleneğini devam ettirmiştir.'),
  ('Kemani Tatyos Efendi\'nin eserleri arasında özellikle hangi tür saz eserleri klasik repertuvarda öne çıkar?', 'Saz semaileri', ['Mevlevi ayinleri', 'Kârlar', 'Tekbirler'], 'Tatyos Efendi\'nin saz semaileri bugün de fasıl ve konserlerde en çok çalınan saz eserleri arasındadır.'),
  ('18. yüzyılda yaşamış Tanburi Mustafa Çavuş\'un şarkıları, aynı dönemin kâr ve bestelerine göre hangi özelliğiyle ayrılır?', 'Sade ve halk ağzına yakın olmasıyla', ['Büyük usullerle yazılmasıyla', 'Farsça güfteler kullanmasıyla', 'Terennümle başlayıp terennümle bitmesiyle'], 'Tanburi Mustafa Çavuş, sade dilli, kolay akılda kalan şarkılarıyla şarkı formunun yaygınlaşmasına öncülük etmiştir.'),
  ('Lale Devri olarak anılan dönemde şarkı güftesi olarak çok bestelenen, şarkı nazım biçimini sevdiren divan şairi hangisidir?', 'Nedim', ['Fuzuli', 'Baki', 'Nef\'i'], 'Nedim\'in şarkıları Lale Devri\'nin eğlence hayatını yansıtır ve birçok bestekâr tarafından bestelenmiştir.'),
  ('Dede Efendi\'nin bestelediği Mevlevi ayinlerinin büyük bir bölümünün bugün eksiksiz icra edilebilmesi en çok hangi gelişmeye bağlıdır?', 'Eserlerin meşk ve notayla kayda geçirilmesi', ['Ses kaydının 18. yüzyılda icadı', 'Ayinlerin Batı senfoni orkestrasına uyarlanması', 'Ayinlerin yalnız sözlü anlatılması'], 'Dede Efendi\'nin eserleri hem güçlü meşk zinciriyle hem de 19. yüzyılda Hamparsum notası gibi sistemlerle yazılı olarak korunmuştur.'),
  ('Bir araştırmacı, 19. yüzyılın ortasında saray çevresinde Batı müziğinin yayılmasına karşın klasik fasıl geleneğini sürdüren bestecileri listeliyor. Aşağıdakilerden hangisi bu listeye girmez?', 'Ali Ufki', ['Dellalzade İsmail Efendi', 'Zekai Dede', 'Hacı Arif Bey'], 'Ali Ufki 17. yüzyılda yaşamıştır; öteki üçü 19. yüzyıl bestecileridir.'),
  ('Tanburi Cemil Bey\'in plak kayıtlarının, yalnız bestelerinden daha çok tartışılıp örnek alınmasının nedeni nedir?', 'Taksimlerindeki icra üslubunu belgelemesi', ['Notaya alınamayan eserler içermesi', 'Batı senfoni orkestrasıyla çalmış olması', 'Sözlü eser okuması'], 'Cemil Bey\'in taksim kayıtları, onun tavrını ve çalım tekniğini sonraki kuşaklara doğrudan aktarmıştır.'),
  ('Tanburi Cemil Bey\'in besteleri arasında en çok hangi tür eserler öne çıkar?', 'Peşrev ve saz semaileri', ['Mevlevi ayinleri', 'Kârlar ve besteler', 'Tekbir, salâ ve temcid gibi okumalar'], 'Bir sazende olan Cemil Bey\'in en tanınmış besteleri peşrev ve saz semaileri gibi saz eserleridir.'),
  ('Arel-Ezgi-Uzdilek sisteminin oluşturulmasında fizik ve akustik bilgisiyle katkı sağlayan isim hangisidir?', 'Salih Murat Uzdilek', ['Rauf Yekta', 'Suphi Ezgi', 'Hüseyin Saadettin Arel'], 'Uzdilek bir fizikçi olarak aralıkların akustik hesaplarına katkı sağlamıştır.'),
  ('Suphi Ezgi\'nin musiki dışındaki asıl mesleği hangisiydi?', 'Doktorluk', ['Avukatlık', 'Mühendislik', 'Öğretmenlik'], 'Dr. Suphi Ezgi askerî doktordur; musiki nazariyatı ve eserlerin notaya alınmasında önemli çalışmalar yapmıştır.'),
  ('İstanbul Radyosu\'nun yayına başladığı 1927 yılından sonra radyonun Türk sanat müziği üzerindeki en belirgin etkisi ne olmuştur?', 'Eserlerin geniş kitlelere ulaşması', ['Fasıl geleneğinin tamamen bitmesi', 'Makamların sayısının azalması', 'Mevlevi ayinlerinin radyoda doğması'], 'Radyo, meclis ve gazinoyla sınırlı kalan icraları evlere taşıyarak sanatçıları ve eserleri geniş kitlelere tanıttı.'),
  ('Zeki Müren 1996\'da hangi kentte, bir televizyon programı sırasında hayatını kaybetmiştir?', 'İzmir', ['İstanbul', 'Bursa', 'Ankara'], 'Zeki Müren, 24 Eylül 1996\'da İzmir\'de TRT\'nin düzenlediği bir törende kalp krizi geçirerek ölmüştür.'),
  ('Zeki Müren\'in uzun yıllar yaşadığı ve ölümünden sonra müzeye dönüştürülen evi hangi ilçededir?', 'Bodrum', ['Mudanya', 'Çeşme', 'Ayvalık'], 'Bodrum\'daki evi bugün Zeki Müren Sanat Müzesi olarak ziyaret edilmektedir.'),
  ('Plak kayıtlarının ilk yıllarında bir kayıt yüzü yalnız birkaç dakika sürebiliyordu. Bu teknik sınırlama hangi tür eserlerin kaydını en çok zorlaştırmıştır?', 'Kâr ve beste gibi uzun eserlerin', ['Kısa şarkıların', 'Kısa taksimlerin', 'Tek bölümlü ve kısa süren saz eserlerinin'], 'Uzun ve büyük usullü eserler birkaç dakikaya sığmadığından kısaltılarak ya da hiç kaydedilmemiştir.'),
  ('Camide farz namaza başlanacağını cemaate bildirmek için müezzinin okuduğu, ezana benzeyen ama daha kısa ve hızlı okunan metin hangisidir?', 'Kamet', ['Temcid', 'Salâ', 'Münacat'], 'Kamet, namazın hemen başında okunur ve ezandan daha hızlı ve süslemesiz bir okuyuştur.'),
  ('Allah\'a yalvarış ve yakarış konulu, çoğunlukla usulsüz ve doğaçlama okunan dinî eserlere ne ad verilir?', 'Münacat', ['Tevşih', 'Peşrev', 'Miraciye'], 'Münacat, kulun Allah\'a yakarışını dile getiren serbest okunuşlu dinî bir türdür.'),
  ('Süleyman Çelebi\'nin halk arasında \'Mevlid\' diye bilinen eserinin asıl adı nedir?', 'Vesiletü\'n-Necat', ['Mesnevi', 'Divan-ı Kebir', 'Hilye-i Şerif'], 'Süleyman Çelebi\'nin eseri \'Vesiletü\'n-Necat\' (kurtuluş vesilesi) adını taşır; Mesnevi ve Divan-ı Kebir Mevlana\'nındır.'),
  ('Bir mevlidhanın Mevlid\'in her bahrini farklı bir makamda okuması, Türk dinî musikisinde hangi beceriye dayanır?', 'Doğaçlama makam geçkisine', ['Büyük usulleri ezberlemeye', 'Saz eşliğini yönetmeye', 'Batı notası okumaya'], 'Mevlid bahirleri çoğunlukla usulsüz ve doğaçlama okunur; mevlidhan makamlar arasında uygun geçkiler yapar.'),
  ('Tekkelerde zikir ve ilahileri yöneten, ilahi okuyanların başındaki kişiye ne ad verilir?', 'Zakirbaşı', ['Mehterbaşı', 'Ser-sazende', 'Kudümzen'], 'Tekke musikisinde ilahi okuyanlara zakir, bunların başına zakirbaşı denir.'),
  ('Mevlevi ayininde müzisyenlerin oturduğu yükseltilmiş bölüme verilen ad ile bu topluluğun adı aynıdır. Bu ad hangisidir?', 'Mutrib', ['Semahane', 'Postnişin', 'Selamlık'], 'Hem ayini icra eden çalgıcı ve okuyucu topluluğuna hem de onların oturduğu yere mutrib denir.'),
  ('Mevlevi ayinleri neden klasik Türk müziğinin en büyük ve en ağır bestelerinden sayılır?', 'Dört selamdan oluşup büyük usuller içerdiği için', ['Tek bir şarkıdan ibaret olduğu için', 'Yalnız Batı çalgılarıyla icra edildiği için', 'Hiç usul içermediği için'], 'Bir ayin; na\'t, taksim, peşrev, dört selam, son peşrev ve son yürük semaiden oluşan geniş bir bütündür.'),
  ('Mevlevi ayinlerinde semazenlerin başlarındaki keçe başlığa ne ad verilir?', 'Sikke', ['Tennure', 'Destar', 'Hırka'], 'Sikke, Mevlevilerin giydiği uzun keçe başlıktır; tennure ise dönerken açılan eteklik giysidir.'),
  ('Bir müezzinin aynı gün içinde ezanı farklı vakitlerde farklı makamlarla okuması, cami musikisinin hangi özelliğini gösterir?', 'Makam çeşitliliğinin ibadet içinde de yaşaması', ['Usulün ezanda zorunlu olması', 'Ezanın notadan okunması gerektiği', 'Ezanın kudüm eşliğiyle yönetilmesi'], 'Ezan usulsüz okunsa da makamlı bir okuyuştur; vakte göre makam seçmek bir gelenektir.'),
  ('Bir öğrenci aynı aralık düzenini önce dügâhta, sonra rastta kuruyor ve iki farklı makam adı buluyor. Bu sonuç en iyi nasıl açıklanır?', 'Durak değişince makamın adı ve rengi değişir', ['Aralıklar göçürmede mutlaka bozulur', 'Rast perdesinde hiçbir makam kurulamaz', 'Göçürme yalnız usulü değiştirir'], 'Göçürmede aralıklar korunur; durak perdesi değiştiği için ortaya farklı adla anılan şed makamlar çıkar.'),
  ('Acemaşiran, Hüseyniaşiran ve Sultaniyegâh makamlarının ortak özelliği nedir?', 'Kaba bölgede karar vermeleri', ['Hicaz ailesinden olmaları', 'Basit makam sayılmaları', 'Duraklarının dügâh perdesi olması'], 'Üç makam da rast perdesinin altındaki kaba bölgede (acemaşiran, hüseyniaşiran, yegâh) karar verir.'),
  ('Uşşak makamının seyir türü hangisidir?', 'Çıkıcı', ['İnici', 'İnici-çıkıcı', 'Serbest'], 'Uşşak seyrine dügâh civarından başlar, güçlü nevaya çıkar ve durakta karar verir; bu çıkıcı seyirdir.'),
  ('Bir dinleyici, bir eserin Uşşak mı Bayati mi olduğunu ayırt etmek istiyor. En güvenilir ipucu hangisidir?', 'Ezginin hangi bölgeden başladığı', ['Eserin usulü', 'Eserin güftesinin hangi dilde olduğu', 'Çalgıların sayısı'], 'Uşşak ile Bayati aynı diziyi kullanır; ayrım seyirde, özellikle başlangıç bölgesindedir.'),
  ('Bir öğrenci, \'Bir makamda yeden perdesi durağın bir üst perdesidir\' diyor. Bu ifade nasıl değerlendirilir?', 'Yanlış; yeden durağın bir alt perdesidir', ['Doğru; yeden durağın üstündedir', 'Yanlış; yeden güçlünün hemen üstündeki perdedir', 'Doğru; yeden makamın güçlüsüdür'], 'Yeden, durağın hemen altında yer alıp ezgiyi durağa yönelten perdedir.'),
  ('Bir makamın dizisini, durağı ve güçlüsünü bilen bir öğrencinin o makamda eser okuyabilmesi için öğrenmesi gereken en önemli ek bilgi nedir?', 'Seyir', ['Mertebe', 'Velvele', 'Ahenk'], 'Makamı belirleyen ögeler dizi, durak, güçlü ve seyirdir; seyir bilinmeden makam doğru yansıtılamaz.'),
  ('Birleşik makamlar için hangi genelleme doğrudur?', 'İki ya da daha çok dizinin özelliklerini birlikte taşırlar', ['Yalnızca tek bir dörtlüden oluşurlar', 'Hiçbir zaman durak perdesi bulunmaz', 'Yalnız sözlü eserlerde kullanılırlar'], 'Birleşik makamlar farklı makamların dizi ve seyir özelliklerini bir araya getirir; durak çoğunlukla bitilen makama göre belirlenir.'),
  ('Bir bestekârın daha önce kullanılmamış bir dizi ve seyir düzeni ortaya koyarak yeni bir makam oluşturmasına ne ad verilir?', 'Terkip', ['Göçürme', 'Meşk', 'Tavır'], 'Yeni makam oluşturmaya terkip denir; III. Selim\'in Suzidilara\'yı terkip etmesi bunun örneğidir.'),
  ('Klasik bir fasıl heyetinde sazendelerin başında bulunan ve topluluğun çalgı bölümünü yöneten kişiye ne ad verilir?', 'Ser-sazende', ['Ser-hanende', 'Kudümzenbaşı', 'Mehterbaşı'], 'Sazendelerin başına ser-sazende, okuyucuların başına ser-hanende denir.'),
  ('Bir fasıl heyeti Hicaz faslı hazırlıyor. Peşrev, kâr, beste, semailer ve saz semaisi seçilirken aşağıdakilerden hangisi kurala aykırı olur?', 'Saz semaisini Rast makamından seçmek', ['Kârı ve besteyi farklı bestecilerden seçmek', 'Ağır semaiyi Aksak semai usulünden seçmek', 'Peşrevden önce Hicaz taksimi yapmak'], 'Klasik fasılda bütün eserler aynı makamda olmalıdır; Rast saz semaisi Hicaz faslına uymaz.'),
  ('20. yüzyılda gazinolarda yaygınlaşan fasıl anlayışı, klasik fasıldan en çok hangi yönüyle ayrılır?', 'Şarkı ve oyun havalarına ağırlık vermesiyle', ['Yalnız kâr ve beste gibi ağır formları içermesiyle', 'Hiç saz kullanmamasıyla', 'Mevlevi ayini düzeninde olmasıyla'], 'Gazino fasıllarında ağır formlar yerine şarkılar, oyun havaları ve hafif eserler öne çıkmıştır.'),
  ('Bir öğrenci aynı Saba eserini iki ayrı ustanın meşkinden öğreniyor ve süslemelerin farklı olduğunu görüyor. Bu durumun en olası açıklaması nedir?', 'Ustaların tavırlarının farklı olması', ['Eserin iki farklı makamda bestelenmiş olması', 'Usulün yanlış vurulması', 'Eserin farklı bestecilere ait olması'], 'Meşkle aktarılan eserlerde her ustanın tavrı ezginin süslemelerine yansır.'),
  ('Meşk geleneğinde bir eserin öğrenilmesinde usul vurmanın, ezgiyi tekrarlamakla birlikte yapılmasının asıl amacı nedir?', 'Ezgiyi ritim kalıbıyla birlikte ezberlemek', ['Eseri notaya geçirmek', 'Makamı değiştirip geçki öğrenmek', 'Güfteyi başka dile çevirmek'], 'Meşkte eser hece hece okunurken usul de vurulur; böylece ezgi ve usul birlikte belleğe yerleşir.'),
  ('Notanın yaygınlaşmasına karşın Türk müziği eğitiminde meşkin hâlâ önemsenmesinin en güçlü gerekçesi hangisidir?', 'Notanın tavır ve süslemeyi tam yansıtamaması', ['Notanın makam adlarını hiçbir şekilde yazamaması', 'Notanın usulü hiç göstermemesi', 'Notanın yalnız Batı\'da okunabilmesi'], 'Nota iskeleti verir; süsleme, nüans ve tavır büyük ölçüde ustadan dinlenerek öğrenilir.'),
  ('Bir araştırmacı, 17. yüzyıldaki bir şarkının güftesini ve usulünü bir güfte mecmuasında buluyor ama ezgisine ulaşamıyor. Bu durumun nedeni en iyi nasıl açıklanır?', 'Mecmuaların ezgiyi değil sözleri kaydetmesi', ['Ezginin padişah emriyle yasaklanmış olması', 'Eserin hiç okunmamış olması', 'Usulün o dönemde bilinmemesi'], 'Güfte mecmuaları ezgi kaydetmez; meşk zinciri koptuysa ezgi kaybolmuş olabilir.'),
  ('Türk müziği notasında bir perdenin bir bakiye (4 koma) pestleşeceğini gösteren işarete ne ad verilir?', 'Bakiye bemolü', ['Koma bemolü', 'Büyük mücenneb bemolü', 'Natürel'], 'AEU yazısında bakiye bemolü sesi 4 koma pestleştirir; koma bemolü 1, büyük mücenneb bemolü 8 koma pestleştirir.'),
  ('AEU yazısında büyük mücenneb diyezi bir sesi kaç koma tizleştirir?', '8', ['4', '5', '13'], 'Büyük mücenneb diyezi, adındaki aralık kadar, yani 8 koma tizleştirir.'),
  ('Segâh perdesinden neva perdesine olan aralık, segâh–çargâh (küçük mücenneb) ile çargâh–neva (tanini) aralıklarının toplamıdır. Bu aralık kaç komadır?', '14', ['13', '17', '140'], '5 + 9 = 14 koma.'),
  ('Rast perdesinden hüseyni perdesine kadar olan aralık, rast–neva tam beşlisine neva–hüseyni taninisinin eklenmesiyle bulunur. Bu aralık kaç komadır?', '40', ['39', '120', '36'], '31 + 9 = 40 koma.'),
  ('AEU sisteminde \'koma\' teriminin karşılığı nedir?', 'Tam tonun dokuzda biri kadar küçük aralık', ['Yarım tonun tam karşılığı olan aralık', 'Bir oktavın on ikide biri kadar aralık', 'Bir dörtlünün yarısı kadar aralık'], 'AEU\'da tam ton (tanini) 9 komaya bölünür; koma bu bölmenin birimidir.'),
  ('Türk müziği notası Batı porte yazısını kullansa da koma, bakiye ve mücenneb için özel değiştirici işaretlere başvurur. Bunun temel nedeni nedir?', 'Bildik diyez ve bemolün komalı aralıkları gösterememesi', ['Batı işaretlerinin Osmanlıca yazılamaması', 'Usullerin porte üzerinde gösterilememesi', 'Türk müziğinde oktav kavramının bulunmaması'], 'Batı diyez ve bemolü yaklaşık yarım tonluk değişimi gösterir; Türk müziğindeki 1, 4, 5 ve 8 komalık farklar için ayrı işaretler gerekir.'),
  ('Peşrevlerin büyük bölümü hangi tür usullerle bestelenir?', 'Büyük usullerle', ['Yalnız 2 zamanlı usullerle', 'Usulsüz biçimde', 'Yalnız Semai usulüyle'], 'Peşrevler çoğunlukla Devr-i kebir, Muhammes, Fahte, Berefşan gibi büyük usullerle yazılır.'),
  ('Saz semaisinin dördüncü hanesinde usul değişikliğinin dinleyici üzerinde yarattığı başlıca etki nedir?', 'Esere canlılık ve hareket katması', ['Eseri ağırlaştırıp yavaşlatması', 'Eseri tamamen usulsüz bir taksime dönüştürmesi', 'Makamı tamamen değiştirmesi'], 'Dördüncü hane çoğunlukla daha hareketli bir usulle (ör. Yürük semai) yazılır; bu, eserin sonuna canlılık katar.'),
  ('Bir peşrev Devr-i kebir (28 zaman) usulünde yazılmış; her hanesi 3 devir, teslimi 2 devirdir. Bir hane ile ardından gelen teslim toplam kaç zaman sürer?', '140', ['112', '1400', '196'], '(3 + 2) x 28 = 140 zaman.'),
  ('Fasılda peşrevin, sözlü eserlerden önce çalınmasının işlevi en iyi nasıl açıklanır?', 'Faslın makamını ve havasını kurmak', ['Faslın sona erdiğini dinleyiciye haber vermek', 'Hanendelere usul öğretmek', 'Dinleyiciyi dansa kaldırmak'], 'Peşrev, taksimden sonra makamı genişçe sunarak sözlü eserlere zemin hazırlar.'),
  ('Mevlevi ayinlerinde selamlardan önce çalınan peşrev ile fasılda çalınan peşrev arasındaki ortak nokta nedir?', 'İkisinin de giriş işlevi görmesi', ['İkisinin de sözlü olması', 'İkisinin de usulsüz olması', 'İkisinin de ayin sonunda çalınması'], 'Hem ayinde hem fasılda peşrev, asıl bölümlere geçmeden önce giriş işlevi görür.'),
  ('Şarkı formundaki nakarat ile peşrevdeki teslim arasındaki benzerlik nedir?', 'İkisinin de bölümler arasında tekrarlanması', ['İkisinin de sözsüz ve usulsüz olması', 'İkisinin de yalnız sonda bulunması', 'İkisinin de yalnızca saz eserlerinde bulunması'], 'Nakarat şarkıda, teslim peşrevde tekrarlanan bölümdür; ikisi de eserin bütünlüğünü sağlar.'),
  ('Fasılda yürük semainin ağır semaiden sonra gelmesi, faslın genel kuruluşu hakkında neyi gösterir?', 'Eserlerin ağırdan hafife sıralandığını', ['Eserlerin rastgele dizildiğini', 'Faslın usulsüz bir eserle bittiğini', 'Sözlü eserlerin sonda olduğunu'], 'Fasılda eserler kâr ve besteden semailere doğru giderek hafifleyen bir düzende sıralanır.'),
  ('Ağır semai ile saz semaisinin ilk hanesinin ortak yanı nedir?', 'Aksak semai usulünde olmaları', ['Sözsüz olmaları', 'Yürük semai usulünde olmaları', 'Usulsüz ve doğaçlama okunmaları'], 'Ağır semailer ve saz semailerinin ilk üç hanesi 10 zamanlı Aksak semai usulüyle yazılır.'),
  ('Saz semailerinin dördüncü hanesinde sık görülen ve fasılda ağır semaiden sonra okunan sözlü forma da adını veren 6 zamanlı usul hangisidir?', 'Yürük semai', ['Aksak semai', 'Devr-i kebir', 'Sofyan'], 'Saz semailerinin dördüncü hanesi çoğunlukla 6 zamanlı Yürük semai usulündedir; yürük semai formu da bu usulle yazılır.'),
  ('Rast beşlisi ile nevadaki Hicaz dörtlüsünün birleşmesinden oluşan Suzinak\'ta, eserlerin asma karar için en çok yöneldiği güçlü perde hangisidir?', 'Neva', ['Dügâh', 'Hüseyni', 'Gerdaniye'], 'Suzinak rastta Rast beşlisi ile nevada Hicaz dörtlüsünden oluşur; iki parçanın birleştiği neva güçlüdür.'),
  ('Aşağıdaki makamlardan hangisi AEU\'nun 13 basit makamı arasında yer alır?', 'Karcığar', ['Hüzzam', 'Nikriz', 'Bestenigâr'], 'Karcığar basit makamlardandır; Hüzzam, Nikriz ve Bestenigâr birleşik ya da şed makamlardır.'),
  ('Basit makamların hepsinde ortak olan yapısal özellik nedir?', 'Bir dörtlü ile bir beşlinin birleşmesinden oluşmaları', ['Duraklarının rast perdesi olması', 'Hicaz dörtlüsü içermeleri', 'Seyirlerinin inici olması'], 'Basit makamlar bir dörtlü ve bir beşlinin (sırası değişebilir) eklenmesiyle oluşan tek bir diziye dayanır.'),
  ('Uşşak, Bayati, Neva, Karcığar ve Hüseyni makamlarının dizilerinin ilk dört sesinde ortak olan cins hangisidir?', 'Uşşak dörtlüsü', ['Hicaz dörtlüsü', 'Rast dörtlüsü', 'Çargâh dörtlüsü'], 'Bu makamların hepsi dügâhta Uşşak dörtlüsüyle başlar; Hüseyni\'de bu dörtlü Hüseyni beşlisinin içindedir.'),
  ('Kürdi makamında dügâhtan sonra gelen ilk perde olan kürdi, dügâhtan kaç koma tizdir?', '4', ['5', '8', '13'], 'Kürdi dörtlüsü bakiye ile başlar; bakiye 4 komadır.'),
  ('Aşağıdaki makamlardan hangisinin durağı segâh perdesi değildir?', 'Saba', ['Hüzzam', 'Müstear', 'Segâh'], 'Saba dügâhta karar verir; Hüzzam, Müstear ve Segâh segâhta karar veren makamlardır.'),
  ('Divan edebiyatında \'şarkı\' adı verilen nazım biçiminde her bendin belirli bir dizesinin bentler boyunca tekrarlanması, bestelenmiş şarkıdaki hangi bölüme karşılık gelir?', 'Nakarat', ['Meyan', 'Zemin', 'Aranağme bölümü'], 'Şarkı nazım biçiminde tekrarlanan dize, bestede nakarat olarak okunur.'),
  ('Aşağıdakilerden hangisi kâr ve bestelerde terennüm olarak kullanılan hecelerden biri değildir?', 'Düm-tek', ['Ten-ni', 'Ya-lel-li', 'Dost-aman'], 'Düm ve tek usul vuruşlarının adıdır; terennümde \'ten-ni, ta-na, ya-lel-li, dost, can, aman\' gibi heceler kullanılır.'),
  ('Bir bestede terennüm bölümlerinin uzunluğu güfte bölümlerini aştığında dinleyicinin en belirgin biçimde fark ettiği şey ne olur?', 'Ezginin sözden bağımsız olarak genişlemesi', ['Usulün tamamen ortadan kalkıp eserin serbestleşmesi', 'Makamın her terennümde değişmesi', 'Eserin usulsüz bir gazele dönüşmesi'], 'Terennüm, ezgiyi anlamlı sözlerden bağımsız olarak uzatıp işlemek için kullanılır.'),
  ('Şarkı güftelerinin büyük çoğunluğunun bir dörtlük düzeninde yazılması, şarkı bestesinin hangi yapısıyla örtüşür?', 'Dört mısranın zemin, nakarat, meyan ve nakarata dağıtılmasıyla', ['Dört ayrı makamın sırayla kullanılmasıyla', 'Dört ayrı usulün art arda gelmesiyle', 'Dört hanenin birbirine teslimle bağlanması ve her hanenin ayrı usulde olmasıyla'], 'Klasik şarkıda birinci mısra zemin, ikinci nakarat, üçüncü meyan, dördüncü yine nakarat ezgisiyle okunur.'),
  ('Bestelenmiş bir şarkıda bir kelimenin kuvvetli hecesinin usulün zayıf zamanına düşmesi ve kelimenin yanlış vurgulanması sorununa ne ad verilir?', 'Prozodi hatası', ['Geçki', 'Çeşni', 'Velvele'], 'Söz ile ezgi ve usul arasındaki vurgu uyumuna prozodi denir; uyumsuzluk prozodi hatasıdır.'),
  ('Ankara Radyosu hangi yıl yayına başlamıştır?', '1938', ['1927', '1936', '19380'], 'Ankara Radyosu 28 Ekim 1938\'de yayına başlamıştır; İstanbul Radyosu 1927\'de açılmıştı.'),
  ('TRT\'de Türk sanat müziği eserlerinin yayına girmeden önce bir repertuvar kurulunca incelenmesi uygulamasının amacı neydi?', 'Yayınlanan eserlerde makam, usul ve prozodi niteliğini denetlemek', ['Eserlerin yalnız Batı çalgılarıyla çalınmasını sağlamak', 'Eserleri halk müziğine dönüştürmek', 'Bestecilerin adlarını gizleyerek eserleri anonimleştirmek'], 'Repertuvar kurulları eserleri müzikal ve sözel bakımdan inceleyip yayına uygunluğuna karar veriyordu.'),
  ('Tanburi Cemil Bey\'in oğlu Mesut Cemil\'in radyo yayıncılığındaki rolü düşünüldüğünde, onun Türk sanat müziğine en önemli katkısı hangisidir?', 'Radyoda Türk müziği yayınlarını ve topluluklarını düzenlemesi', ['İlk Türk operasını bestelemesi', 'Mehter takımını yeniden kurması', 'Hamparsum notasını geliştirip yeni bir nota sistemi icat etmesi'], 'Mesut Cemil İstanbul ve Ankara radyolarında Türk müziği programlarını, koro ve toplulukları yönetmiştir.'),
  ('Cumhuriyet döneminde Türk sanat müziği bestecilerinin büyük çoğunluğunun kâr ve beste yerine şarkı formunu seçmesinin en güçlü nedeni hangisidir?', 'Radyo, plak ve gazinonun kısa eserlere uygun olması', ['Büyük usullerin yasaklanması', 'Makamların kaldırılması', 'Klasik formların hiçbir biçimde notaya alınamaması'], 'Kayıt süresi, radyo programları ve gazino sahnesi kısa ve akılda kalıcı eserleri öne çıkarmıştır.'),
  ('1925\'te tekke ve zaviyelerin kapatılmasının Türk müziği üzerindeki en doğrudan etkisi hangisidir?', 'Tekke musikisinin doğal icra ortamını yitirmesi', ['Şarkı formunun yasaklanması', 'Gazinoların kapanması', 'Radyonun kurulup ilk yayınına başlaması'], 'Tekkelerin kapanmasıyla ayin, ilahi ve zikir musikisinin düzenli icra edildiği mekânlar ortadan kalkmıştır.'),
  ('Darülelhan\'ın 1926\'da İstanbul Belediye Konservatuvarı adını almasından sonra burada yürütülen en kalıcı Türk müziği çalışması hangisidir?', 'Klasik eserlerin notaya alınıp yayımlanması', ['Mehterin yeniden kurulması', 'Türk müziğinin tamamen müfredattan çıkarılması', 'Halk danslarının sahnelenmesi'], 'Konservatuvardaki heyet, meşkle yaşayan yüzlerce klasik eseri yazıya geçirip yayımladı.'),
  ('Hamparsum notasının 20. yüzyılda yerini Batı porte notasına bırakmasının başlıca nedeni hangisidir?', 'Batı notasının eğitimde ve yayında yaygınlaşması', ['Hamparsum notasının yasaklanması', 'Hamparsum notasının usul gösterememesi', 'Hamparsum notasının yalnız Ermenice bilenlerce okunabilmesi'], 'Konservatuvar eğitimi ve basılı nota yayıncılığı Batı porte yazısını standart hâle getirmiştir.'),
  ('Kantemiroğlu, Nasır Dede ve Hamparsum\'un geliştirdiği notalar arasındaki ortak amaç nedir?', 'Meşkle aktarılan eserleri yazıyla korumak', ['Batı armonisini Türk müziğine taşımak', 'Makamları sayıca azaltmak', 'Usulleri ortadan kaldırıp serbest okuyuşu yaygınlaştırmak'], 'Üç sistem de sözlü aktarımla kaybolma tehlikesi taşıyan eserleri yazıya geçirmeyi amaçlar.'),
  ('\'Rast\' sözcüğünün Farsçadaki anlamı, bu perdenin sistemdeki yerini nasıl açıklar?', '\'Doğru, düz\' anlamıyla temel başlangıç perdesi olmasını', ['\'Tiz\' anlamıyla en yüksek perde olmasını', '\'Hüzünlü\' anlamıyla minör renkli bir perde olmasını', '\'Kırık\' anlamıyla aksak usulleri'], 'Rast, \'doğru, düz\' anlamına gelir ve dizide temel başlangıç perdesi sayılır.'),
  ('Farsçada \'çâr\' sözcüğü dört anlamına gelir. Buna göre \'çargâh\' perde adının anlamı nedir?', 'Dördüncü yer', ['İkinci yer', 'Beşinci yer', 'Üçüncü yer'], '\'Gâh\' yer, \'çâr\' dört demektir; çargâh rasttan sonra sayılan dördüncü perdedir.'),
  ('Osmanlı sarayında müzik eğitimi alıp daha sonra önemli musikişinas olarak yetişen saray öğrencilerinin eğitildiği okul hangisidir?', 'Enderun', ['Darülfünun', 'Mülkiye', 'Mekteb-i Harbiye'], 'Enderun Mektebi\'nde musiki de öğretilir, birçok saray musikişinası burada yetişirdi.'),
  ('Saray çevresinde gelişen klasik Türk müziği ile tekkelerde gelişen dinî musiki arasındaki ilişki için hangisi en doğrudur?', 'Birçok besteci iki alanda da eser vermiştir', ['İki alan birbirinden tamamen kopuktur', 'Tekke musikisinde makam kullanılmaz', 'Saray musikisi usul kullanmaz, yalnız taksime dayanır'], 'Itri, Dede Efendi, Zekai Dede gibi besteciler hem dindışı hem dinî eserler bestelemiştir.'),
  ('Mevlevihanelerin klasik Türk müziği tarihindeki önemi en iyi nasıl açıklanır?', 'Musiki eğitimi veren merkezler olmaları', ['Yalnız mehter çalgılarının üretildiği yerler olmaları', 'Batı müziğinin öğretildiği ilk okullar olmaları', 'Halk danslarının sahnelendiği yerler olmaları'], 'Mevlevihaneler ney, kudüm, ayin ve nazariyat eğitimiyle birçok bestekâr ve icracı yetiştirmiştir.'),
  ('Klasik Türk müziği için kullanılan \'Osmanlı musikisi\', \'Türk sanat müziği\' ve \'klasik Türk müziği\' adlarının birlikte var olması neyi gösterir?', 'Aynı geleneğin farklı dönem ve bakışlarla adlandırıldığını', ['Bunların birbirinden tamamen ayrı üç müzik olduğunu', 'Bu müziğin yalnız 20. yüzyılda doğduğunu', 'Bu müziğin makamsız olduğunu'], 'Farklı adlar, aynı makam ve usul geleneğinin tarihsel ve kültürel bakış açılarına göre adlandırılmasından doğar.'),
  ('Türk sanat müziği ile Türk halk müziği arasındaki temel ayrım çoğunlukla neye dayanır?', 'Eserlerin bestecisinin bilinip kentli bir gelenekte yetişmesine', ['Birinde makam, ötekinde hiç perde kavramı bulunmamasına', 'Birinin tamamen çalgısız olmasına', 'Birinin yalnız Batı porte notasıyla yazılabilmesine ve okunabilmesine'], 'Sanat müziği eserlerinin çoğunlukla bestecisi bellidir ve saray, tekke, şehir çevrelerinde gelişmiştir; halk müziğinde anonim eserler ağır basar.'),
  ('Bir eser künyesinde form olarak \'Durak\' yazılmışsa bu eser büyük olasılıkla hangi ortamda okunmak için bestelenmiştir?', 'Tekkede', ['Gazinoda', 'Mehterde', 'Kanto sahnesinde'], 'Durak, tekke musikisine ait dinî bir formdur.'),
  ('İlahilerin tekke musikisinde topluca okunmasını kolaylaştıran özellikleri arasında hangisi yer almaz?', 'Büyük ve karmaşık usuller kullanılması', ['Ezgilerinin kısa ve tekrarlı olması', 'Güftelerin sade Türkçe ile yazılmış olması', 'Nakarat benzeri tekrarlar içermesi'], 'İlahiler çoğunlukla küçük usullerle yazılır; büyük ve karmaşık usuller topluca okumayı zorlaştırır.'),
  ('Uşşak makamında durağın hemen altında bulunan ve ezgiyi durağa yönelten yeden perdesi hangisidir?', 'Rast', ['Segâh', 'Irak', 'Neva'], 'Dügâhın bir tanini altındaki rast, Uşşak\'ta yeden olarak kullanılır.'),
  ('Buselik makamının dizisi dügâhta hangi beşliyle başlar?', 'Buselik beşlisi', ['Rast beşlisi', 'Hicaz beşlisi', 'Hüseyni beşlisi'], 'Buselik makamı dügâhta Buselik beşlisi ile hüseynide Kürdi dörtlüsünden oluşur.'),
  ('Durağı do perdesinde olan ve aralıkları Batı majörüne denk düşen basit makamın dizisi, aşağıdaki parça çiftlerinden hangisiyle kurulur?', 'Çargâh beşlisi ve Çargâh dörtlüsü', ['Rast beşlisi ve Uşşak dörtlüsü', 'Buselik beşlisi ve Kürdi dörtlüsü', 'Hicaz beşlisi ve Hicaz dörtlüsü'], 'Çargâh makamı çargâhta Çargâh beşlisi ile gerdaniyede Çargâh dörtlüsünden kurulur.'),
  ('Kürdi, Acemkürdi, Muhayyerkürdi ve Kürdilihicazkâr makamlarını aynı aile altında toplayan ortak özellik nedir?', 'Kürdi dörtlüsünün belirleyici olması', ['Duraklarının hep rast perdesi olması', 'Hicaz dörtlüsü içermeleri', 'Tümünün inici seyirli olması'], 'Bu makamların hepsinde durak üzerinde bakiye ile başlayan Kürdi dörtlüsü belirleyicidir.'),
  ('Segâh, Hüzzam ve Müstear makamlarının tek bir ailede düşünülmesinin nedeni nedir?', 'Segâh perdesinde karar vermeleri', ['Tümünün Kürdi dörtlüsü kullanması', 'Tümünün rastta karar vermesi', 'Tümünün Hicaz ailesinden sayılması'], 'Bu makamlar segâh perdesinde karar veren ve segâh rengini taşıyan makamlardır.'),
  ('Neva perdesinden muhayyer perdesine kadar olan aralık, neva–hüseyni taninisi, hüseyni–acem bakiyesi ve acem–gerdaniye taninisi ile gerdaniye–muhayyer taninisinin toplamıdır. Bu aralık kaç komadır?', '31', ['124', '35', '40'], '9 + 4 + 9 + 9 = 31 koma; bu bir tam beşlidir.'),
  ('Bir öğrenci, Hicaz dörtlüsünde dügâhtan nim hicaz perdesine olan aralığı hesaplamak istiyor. Dügâh–dik kürdi 5 koma, dik kürdi–nim hicaz 12 koma ise dügâh–nim hicaz kaç komadır?', '17', ['170', '13', '22'], '5 + 12 = 17 koma.'),
  ('Rast perdesinden dügâha 9, dügâhtan segâha 8 koma vardır. Rastta kurulmuş bir dizide segâh yerine buselik kullanılırsa rast ile üçüncü derece arasındaki aralık kaç komaya çıkar?', '18', ['17', '180', '22'], 'Rast–dügâh 9, dügâh–buselik 9 komadır; toplam 18 koma olur.'),
  ('Bir kârın bir bölümü Zencir usulünün (120 zaman) bir devrini kapsıyor ve her zaman yaklaşık 0,5 saniye sürüyor. Bu bölüm yaklaşık kaç dakika sürer?', '1', ['2', '1,5', '0,5'], '120 x 0,5 = 60 saniye, yani 1 dakika.'),
  ('Bir peşrevin dört hanesi sırasıyla 2, 2, 3 ve 2 devir Muhammes (32 zaman) usulündedir. Teslim hariç peşrev kaç zamandır?', '288', ['256', '320', '1152'], '(2 + 2 + 3 + 2) x 32 = 9 x 32 = 288 zaman.'),
  ('Fahte usulü (20 zaman) ile Lenk fahte usulü (10 zaman) aynı tempoda vuruluyor. Fahte\'nin 3 devri süresince Lenk fahte kaç devir tamamlar?', '6', ['12', '4', '5'], 'Fahte\'nin 3 devri 60 zamandır; 60 / 10 = 6 devir.'),
  ('\'Çifte düyek\' adındaki \'çifte\' sözcüğü, Düyek\'in 8 zaman olduğu bilindiğine göre usulün zaman sayısını nasıl açıklar?', 'İki Düyek\'in birleşmesiyle 16 zaman olmasını', ['Düyek\'in yarısı kadar, yani 4 zaman olmasını', 'Düyek ile aynı, 8 zaman olmasını', 'Düyek\'in üç katı, 24 zaman olmasını'], 'Çifte düyek, iki Düyek\'in art arda bağlanmasıyla oluşan 16 zamanlı bir usuldür.'),
  ('Bir eser rastta karar veriyor; rasttan nevaya Rast beşlisi, nevadan gerdaniyeye ise Rast dörtlüsü kullanılıyor ve ezgi çıkıcı bir seyir izliyor. Eser hangi makamdadır?', 'Rast', ['Mahur', 'Suzinak', 'Nihavend'], 'Rastta Rast beşlisi ve nevada Rast dörtlüsüyle çıkıcı seyir Rast makamının özellikleridir.'),
  ('Mevlevi ayininin bölümleri aşağıdaki sıralamaların hangisinde doğru verilmiştir?', 'Na\'t, ney taksimi, peşrev, dört selam, son peşrev, son yürük semai', ['Peşrev, na\'t, dört selam, ney taksimi, son peşrev', 'Dört selam, na\'t, peşrev, son yürük semai', 'Ney taksimi, son peşrev, na\'t, dört selam'], 'Ayin na\'t ve ney taksimiyle açılır, Devr-i Veledi peşreviyle devam eder, dört selamdan sonra son peşrev ve son yürük semai çalınır.'),
  ('Bir Mevlevi ayininde selamların farklı usullerle bestelenmesi esere nasıl bir yapı kazandırır?', 'Bölümler arasında tempo ve karakter değişimi', ['Bütün ayinin tek tempoda sürmesi', 'Ayinin usulsüz bir taksime dönüşmesi', 'Selamların birbirinden ayırt edilememesi'], 'Devr-i revan, Evfer, Devr-i kebir, Semai gibi usullerin sırayla gelmesi ayine değişen bir karakter verir.'),
  ('Aşağıdaki musikişinaslar yaşadıkları döneme göre eskiden yeniye doğru hangi seçenekte doğru sıralanmıştır?', 'Meragi, Itri, Dede Efendi, Tanburi Cemil', ['Itri, Meragi, Tanburi Cemil, Dede Efendi', 'Dede Efendi, Itri, Meragi, Tanburi Cemil Bey', 'Meragi, Dede Efendi, Itri, Tanburi Cemil'], 'Meragi 14-15., Itri 17., Dede Efendi 18-19., Tanburi Cemil 19-20. yüzyılda yaşamıştır.'),
  ('Bir konser kitapçığında sanatçılar çalgılarıyla birlikte tanıtılıyor. Kitapçıktaki eşleştirmelerden hangisi doğrudur?', 'Kutbünnayi Osman Dede – ney', ['Ali Ufki – kemençe', 'Tanburi Cemil Bey – kanun', 'Şükrü Tunar – tanbur ve yaylı tanbur'], 'Osman Dede neyzendir; Ali Ufki santur, Tanburi Cemil tanbur ve kemençe, Şükrü Tunar klarnet çalmıştır.'),
  ('Musiki tarihine ait kitap ve derlemeleri yazarlarıyla eşleştiren bir listede hangi eşleştirme yanlıştır?', 'Itri – Rehber-i Musiki', ['Ali Ufki – Mecmua-i Saz ü Söz', 'Abdülkadir Meragi – Câmiu\'l-Elhân', 'Hafız Post – güfte mecmuası derlemesi'], 'Rehber-i Musiki Tanburi Cemil Bey\'in kitabıdır; Itri böyle bir kitap yazmamıştır.'),
  ('Osmanlı döneminde geliştirilen nota sistemlerini geliştiricileriyle eşleştiren aşağıdaki seçeneklerden hangisi doğrudur?', 'Abdülbaki Nasır Dede – Tahririye notası', ['Hamparsum – ebced harflerine dayanan nota', 'Ali Ufki – Hamparsum notası', 'Kantemiroğlu – Tahririye notası'], 'Tahririye Nasır Dede\'nin, Hamparsum notası Hamparsum\'un geliştirdiği nota sistemidir.'),
  ('Besteci padişahları mahlasları ve terkip ettikleri makamlarla eşleştiren bir öğrencinin yaptığı eşleştirmelerden hangisi yanlıştır?', 'III. Selim – Adli', ['II. Mahmud – Adli mahlası', 'III. Selim – İlhami mahlası', 'III. Selim – Suzidilara makamı'], 'III. Selim\'in mahlası İlhami\'dir; Adli II. Mahmud\'un mahlasıdır.'),
  ('Klasik Türk müziğinin geleneksel icrasında armoni ve çok seslilik yerine öne çıkan temel özellik hangisidir?', 'Tek sesli ezginin makam içinde işlenmesi', ['Akorların bas çizgisi üzerine kurulması', 'Dört sesli koro yazısı', 'Birbirinden bağımsız ezgilerin kontrpuanı'], 'Geleneksel klasik Türk müziği tek seslidir; zenginlik makam, seyir, usul ve süslemeden gelir.'),
  ('Bir Batı müziği öğrencisi fasıl dinledikten sonra \'Herkes aynı ezgiyi çalıyor ama tam aynı değil\' diyor. Bu gözlem hangi kavramı tarif eder?', 'Heterofonik doku', ['Modülasyon', 'Kanon', 'Senkop'], 'Aynı ezginin icracılar tarafından küçük farklarla eş zamanlı çalınması heterofonik dokudur.'),
  ('Aşağıdaki çalgılardan hangisi perdeleri sabit olduğu için Türk müziğindeki komalı aralıkların bazılarını vermekte en çok zorlanır?', 'Klasik piyano', ['Ud', 'Ney', 'Klasik kemençe'], 'Ud perdesiz, ney nefes ve parmakla ayar yapılabilen, kemençe tırnakla serbest basılan çalgılardır; piyanonun perdeleri sabittir.'),
  ('Kanundaki mandallar sayesinde bir kanuni hangi işi çalmayı durdurmadan yapabilir?', 'Bir perdeyi koma düzeyinde tizleştirip pestleştirmek', ['Çalgının teknesini değiştirmek', 'Yayla çalmaya geçmek', 'Usulü kudüm gibi vurmak ve eşlik etmek'], 'Mandallar tellerin boyunu küçük adımlarla değiştirerek perdeyi koma düzeyinde ayarlar.'),
  ('Udda tellerin çoğunun ikişer ikişer (çift) takılmasının icracıya sağladığı başlıca yarar nedir?', 'Sesin daha dolgun ve güçlü çıkması', ['Perdelerin sapta sabitlenmesi', 'Usulün kendiliğinden vurulması', 'Çalgının yayla da çalınabilmesi'], 'Aynı sese akort edilen çift teller birlikte titreşerek sesi güçlendirir ve dolgunlaştırır.'),
  ('Ali Ufki ile Kantemiroğlu\'nun eserleri kaydetme yöntemleri arasındaki temel fark nedir?', 'Ali Ufki Batı portesini, Kantemiroğlu harfli bir notayı kullanmıştır', ['İkisi de Hamparsum notasını kullanmıştır', 'Ali Ufki yalnız güfteleri, Kantemiroğlu ise yalnız usulleri yazıya geçirmiştir', 'İkisi de eserleri ses kaydıyla belgelemiştir'], 'Ali Ufki Avrupa\'da öğrendiği porte yazısını, Kantemiroğlu ise kendi geliştirdiği harf esaslı notayı kullanmıştır.'),
  ('Kuran\'ın harflerinin doğru çıkarılması ve okunuş kurallarını inceleyen, hafızların ve müezzinlerin eğitiminde temel olan bilgi alanı hangisidir?', 'Tecvid', ['Edvar', 'Aruz', 'Usul'], 'Tecvid, Kuran okuyuşunun kurallarını düzenler; makamlı okuyuş bu kurallara bağlı kalarak yapılır.'),
  ('Bir hafızın Kuran\'ı makamlı olarak okurken hangi ilkeye öncelik vermesi beklenir?', 'Okuyuş kurallarını ezgi süslemelerine feda etmemek', ['Usulü kudümle tutmak', 'Her ayette makam değiştirmek', 'Okuyuşu saz eşliğinde ve usullü olarak yapmak'], 'Dinî okumalarda makam sözün doğru okunmasına hizmet eder; süsleme okuyuş kurallarını bozmamalıdır.'),
  ('Mevlevi ayininde şeyhin, semahanenin bir yanında serili kırmızı post üzerinde oturması nedeniyle ona verilen ad hangisidir?', 'Postnişin', ['Semazenbaşı', 'Kudümzenbaşı', 'Na\'than'], 'Postnişin \'post üzerinde oturan\' demektir ve tekkenin şeyhini anlatır.'),
  ('Bir öğretmen öğrencilerine aynı ezgiyi önce 8 zamanlı Düyek, sonra 8 zamanlı Müsemmen usulüyle vurduruyor. Öğrencilerin fark ettiği farkın kaynağı nedir?', 'Vuruşların dağılımı', ['Zaman sayısı', 'Makamın durağı', 'Güftenin vezni ve hece sayısı'], 'Düyek ve Müsemmen aynı zaman sayısına sahiptir; düm ve teklerin yerleşimi farklıdır.'),
  ('İki usulün zaman sayıları aynı olduğunda onları birbirinden ayıran temel unsur nedir?', 'Düm ve teklerin yerleşimi', ['Makamları', 'Bestecileri', 'Güftelerinin uzunlukları'], 'Aynı zaman sayısındaki usuller vuruş düzeniyle ayrılır; örneğin Aksak ile Evfer.'),
  ('Bir hanende, Saba makamında bir şarkıyı okurken çargâh perdesinde uzunca durup sonra dügâha iniyor. Çargâhta yapılan bu duruş Saba makamı için neden doğaldır?', 'Çargâh Saba\'nın güçlüsü olduğu için', ['Çargâh Saba\'nın durağı olduğu için', 'Çargâh Saba\'da hiç kullanılmadığı için', 'Çargâh Saba\'nın yedeni olduğu için'], 'Saba\'nın güçlüsü çargâhtır; asma kararlar en çok güçlüde yapılır.'),
  ('Hüseyni makamında güçlünün durağa uzaklığı ile Rast makamında güçlünün durağa uzaklığı karşılaştırılırsa hangi sonuç çıkar?', 'İkisinde de güçlü durağın tam beşli üstündedir', ['Hüseyni\'de dörtlü, Rast\'ta beşli üsttedir', 'Hüseyni\'de üçlü, Rast\'ta altılı üsttedir', 'İkisinde de güçlü durağın altında yer alır'], 'Dügâh–hüseyni ve rast–neva aralıklarının ikisi de 31 komalık tam beşlidir.'),
  ('Bir öğrenci Kürdi makamında güçlünün hangi perde olduğunu, dizinin parçalarından yola çıkarak bulmak istiyor. İzlemesi gereken en doğru yol hangisidir?', 'Dörtlü ile beşlinin birleştiği perdeye bakmak', ['Dizinin en tiz perdesine bakmak', 'Dizinin en pes perdesine bakmak', 'Eserin usulüne ve mertebesine bakmak'], 'Basit makamlarda güçlü, çoğunlukla dörtlü ile beşlinin eklendiği perdedir.'),
  ('Bir şarkıcı 6 zamanlı Yürük semai usulünde 20 devir söylemiştir. Aynı sürede 3 zamanlı Semai usulü kaç devir vurulur (tempo aynı)?', '40', ['20', '60', '120'], '20 devir Yürük semai 120 zaman eder. Semai devri 3 zaman olduğundan 120 / 3 = 40 devir vurulur.'),
  ('Bir kudümzen, 9 zamanlı Evfer usulünü dakikada 80 zaman hızında vuruyor. Bir devir kaç saniye sürer?', '6,75', ['4,5', '7,2', '9'], 'Dakikada 80 zaman, zaman başına 60/80 = 0,75 saniyedir. 9 zaman 9 x 0,75 = 6,75 saniye eder.'),
  ('Sofyan (4 zaman) usulünde 18 devir vurulan bir bölümün zaman sayısı, Aksak (9 zaman) usulünde kaç devire denktir?', '8', ['6', '9', '12'], '18 x 4 = 72 zaman; 72 / 9 = 8 devir eder.'),
  ('Bir bestenin zemin bölümü 4 devir Devr-i hindi (7 zaman), meyan bölümü 6 devir Devr-i hindi, nakarat bölümü 3 devir Devr-i hindi sürüyor. Bu üç bölüm toplam kaç zamandır?', '91', ['84', '98', '182'], '4 + 6 + 3 = 13 devir; 13 x 7 = 91 zamandır.'),
  ('Zencir usulünün 120 zamanlık bir devrini bir kudümzen 4 dakikada tamamlıyor. Her zaman kaç saniye sürmüştür?', '2', ['1', '1,5', '3'], '4 dakika 240 saniyedir; 240 / 120 = 2 saniye.'),
  ('Aksaksemai usulünde (10 zaman) bir eserin ilk hanesi 8, ikinci hanesi 8, üçüncü hanesi 6 ölçüden oluşuyor. Üç hane toplam kaç zamandır?', '220', ['1100', '200', '240'], '8 + 8 + 6 = 22 ölçü; 22 x 10 = 220 zaman.'),
  ('Bir hanende, Fahte usulünü (20 zaman) bir devrini tam 10 saniyede vuracak biçimde tempoya bağlıyor. Tempo dakikada kaç zamandır?', '120', ['60', '100', '1200'], '20 zaman 10 saniyede vurulursa saniyede 2 zaman, dakikada 120 zaman olur.'),
  ('Çifte düyek usulünde (16 zaman) bir parça 5 devir çalınıyor. Aynı parça Düyek (8 zaman) olarak yazılsaydı kaç devir tutardı?', '10', ['5', '8', '100'], '5 x 16 = 80 zaman; 80 / 8 = 10 devir.'),
  ('Bir kâr hanesi Devr-i kebir usulünün (28 zaman) 6 devrinden oluşuyor. Teslim 2 devir ise hane ve teslim birlikte kaç zaman eder?', '224', ['1120', '196', '252'], '6 + 2 = 8 devir; 8 x 28 = 224 zaman.'),
  ('Müsemmen usulünde (8 zaman) yazılmış 24 ölçülük bir bölümün kaç saniye süreceğini bulmak için hangi bilginin ayrıca gerekli olduğu söylenebilir?', 'Bir zamanın kaç saniye sürdüğü', ['Bestecinin adı', 'Eserin makamının durağı', 'Güftenin kaç mısradan oluştuğu'], 'Toplam zaman sayısı 24 x 8 = 192\'dir; süre için bir zamanın uzunluğu, yani tempo bilinmelidir.'),
  ('Tempo sabit tutulduğunda, devri 14 zaman olan usulün 5 devri ile devri 7 zaman olan usulün kaç devri aynı sürer?', '10', ['100', '7', '14'], '5 x 14 = 70 zaman; 70 / 7 = 10 devir.'),
  ('\'Meyan\' sözcüğünün Farsçadaki \'orta\' anlamı, şarkı ve beste formunda hangi bölümün yerini açıklar?', 'Zeminden sonra gelen, çoğunlukla tizde dolaşan orta bölümün', ['Eserin ilk bölümünün, yani ana ezginin hemen başında yer alan kısmının', 'Eserin son tekrarından sonra gelen kapanış bölümünün', 'Eserin usulsüz olarak çalınan giriş bölümünün'], 'Meyan, eserin ortasında yer alan ve çoğunlukla tiz bölgede gezinen bölümdür; adı \'orta\' anlamındaki sözcükten gelir.'),
  ('Farsçada \'okuyan\' anlamındaki \'hanende\' ile \'çalan\' anlamındaki \'sazende\' sözcükleri bir fasıl heyetinde hangi iş bölümüne işaret eder?', 'Hanende ses ile söyler, sazende çalgı ile eşlik eder', ['Hanende usulü vurur, sazende güfteyi yazar ve besteciliği üstlenir', 'Hanende bestecidir, sazende ise yalnızca eseri dinleyen kişidir', 'Hanende yalnız tanbur çalar, sazende yalnız ney çalarak eşlik eder'], 'Hanende şarkıyı okuyan, sazende ise çalgıcıdır; fasıl heyeti bu iki grubun birlikte çalışmasıyla kurulur.'),
  ('Sözlü eserlerin sıralandığı bir fasılda şarkıların, kâr ve bestelerden sonra gelmesi hangi eğilimle açıklanır?', 'Ağır ve büyük formlardan hafif ve kısa formlara geçilmesiyle', ['Kısa formlardan uzun formlara doğru giderek yükselen bir düzen izlenmesiyle', 'Usulsüz eserlerin hep faslın sonuna bırakılması geleneğiyle', 'Makamın her eserde değiştirilerek faslın çeşitlendirilmesi anlayışıyla'], 'Klasik fasıl, ağır ve geniş kâr-beste bölümlerinden başlayıp semailer ve şarkılar gibi hafif formlara doğru ilerler.'),
  ('Fasılda peşrevden sonra okunan kâr, \'iş, eser\' anlamındaki Farsça sözcükten adını almıştır. Kârın hangi özelliği, ona bu \'büyük eser\' havasını verir?', 'Büyük usullerle bestelenmiş, geniş ölçekli sözlü bir form olması', ['Yalnızca çalgıyla çalınan ve sözü hiç bulunmayan, kısa ve hızlı bir form olması', 'Tek mısralık, usulsüz ve doğaçlama okunan bir dinî form olması', 'Çocuklar için bestelenmiş, sade ve kısa bir ezgi türü olması'], 'Kâr, büyük usullerle yazılan ve fasılın en ağır sözlü formlarından olan geniş çaplı bir eser türüdür.'),
  ('Bir peşrev ile bir saz semaisi karşılaştırıldığında peşrevde hane sayısının genellikle dört, saz semaisinde ise üç civarında olması neyi gösterir?', 'Her iki formun da hane-teslim düzeniyle kurulduğunu', ['Her iki formun da sözlü olup dört mısralı güfteyle kurulduğunu gösterir', 'İkisinin de usulsüz doğaçlama biçimler olduğunu gösterir', 'İkisinin de aynı usulle yazıldığını ve aynı hızda çalındığını gösterir'], 'İki form da hane ve teslim bölümlerinden oluşur; farklar usul, tempo ve karakterdedir.'),
  ('Peşrevde dördüncü hanenin sonundan sonra teslime dönülmesinin nedeni, formun hangi temel ilkesidir?', 'Hanelerin değişirken eserin ortak ana ezgiye bağlanması', ['Sözlerin her hanenin sonunda baştan okunmasını sağlayan bir kuralı', 'Usulün hanenin sonunda durdurulup yeniden başlatılmasını', 'Makamın her hanede değiştirilerek eserin canlandırılmasını'], 'Teslim, hanelerin arasında ve sonunda dönülen sabit bölümdür; eserin birliğini sağlar.'),
  ('Klasik Türk müziğinde \'kârçe\' adı verilen formun adı, hangi forma göre ne anlama gelir?', 'Kâr formunun küçültülmüş, daha kısa biçimi', ['Kâr formunun usulsüz okunan ve doğaçlamaya dayanan biçimi', 'Kâr formunun yalnız çalgıyla icra edilen sözsüz biçimi', 'Kâr formunun yalnız camide okunan ve çalgısız biçimi'], 'Kârçe, adındaki küçültme ekiyle kârın daha kısa ve hafif bir türü olarak anlaşılır.'),
  ('Peşrev ile kâr arasındaki \'sözlü / sözsüz\' ayrımı gözetilerek, aşağıdaki eser çiftlerinden hangisi her iki türden de birer örnek içerir?', 'Peşrev ve ağır semai', ['Peşrev ve saz semaisi', 'Longa ve sirto', 'Kâr ve beste'], 'Peşrev ve saz semaisi sözsüzdür; kâr, beste, ağır semai ve yürük semai sözlüdür. Seçenekte yalnız peşrev-ağır semai karışık çifttir.'),
  ('Bir bestekâr aynı güfteyi, birinde 4 mısralı beste, diğerinde şarkı biçiminde bestelemek istiyor. Bu iki bestenin ortak yanı hangisi olabilir?', 'İkisinin de sözlü ve dört mısrayı temel alan bir yapıda olması', ['İkisinin de büyük usullerle yazılması ve yalnız çalgıyla seslendirilmesi', 'İkisinin de sazsız okunan ve usulsüz doğaçlamaya dayanan biçimler olması', 'İkisinin de peşrevin yerine geçerek faslı açan eserler olması'], 'Her iki form da sözlüdür ve dört mısralı güfteyi bölümlere ayırır; fark, usul uzunluğu ve ezgi genişliğindedir.'),
  ('Bir öğrenci \'taksim bir eserin bölümü değil, bir icra biçimidir\' diyor. Bu ifadeyi en iyi destekleyen özellik hangisidir?', 'Taksimin önceden bestelenmeyip icra anında oluşturulması', ['Taksimin yalnız sözlü eserlerin içinde yer alan bestelenmiş bir bölüm olmasıyla', 'Taksimin her zaman 28 zamanlı bir usulle ve notaya bağlı çalınmasıyla', 'Taksimin yalnız camide ve topluca yapılan bir okuyuş olmasıyla'], 'Taksim bestelenmiş bir kalıp değil, çalgıcının makam seyri içinde o anda yaptığı doğaçlamadır.'),
  ('Gazel ile taksim arasındaki temel fark nedir?', 'Gazel insan sesiyle, taksim çalgıyla yapılan usulsüz doğaçlamadır', ['Gazel usullü, taksim usulsüzdür; ikisi de yalnız çalgıyla yapılır', 'Gazel yalnız camide, taksim yalnız tekkede yapılan bir okuyuştur', 'Gazel bestelenmiş bir eser, taksim ise hiç doğaçlama içermeyen bir formdur'], 'Her ikisi de usulsüz ve doğaçlamadır; gazel ses, taksim çalgı ile icra edilir.'),
  ('Gazel okurken hanendenin doğaçlama yaptığı sözlerin çoğunlukla ne olduğu söylenebilir?', 'Divan şiirinden bir beyit ya da dörtlük', ['Bir mevlit bahrinin tamamı ve eşlik eden ilahi bölümleri', 'Bir halk türküsünün tekrarlanan nakarat bölümü', 'Bir kâr güftesinin terennüm bölümü ve çalgı girişi'], 'Gazel, makam seyrini işleyen sese ve bir şiir beytinin tekrarlanıp işlenmesine dayanır.'),
  ('Sirto, longa ve köçekçe gibi hafif saz formlarının fasıl içinde genellikle hangi bölümde yer aldığı söylenebilir?', 'Faslın sonuna doğru, hafif bölümde', ['Faslın en başında, açılış olarak', 'Tüm eserlerin ortasında, ağır bölümde', 'Bütün fasıl boyunca arka planda'], 'Bu oyun havasındaki hafif saz formları faslın hafif bölümüne, çoğunlukla sonuna doğru yerleştirilir.'),
  ('Bir udi, ud çalarken tellerin üzerinde hazır perde (bağ) bulunmadığı için ne yapmak zorundadır?', 'Perdelerin yerini kulağıyla bulup parmakla basmak', ['Perde yerine mandal çevirerek sesi koma düzeyinde tizleştirmek ve pestleştirmek', 'Yaya basarak sesi uzatıp perdeleri kaydırarak geçiş yapmak', 'Tellerin üzerine tahta çubuk yerleştirip sesleri sabitlemek'], 'Ud perdesiz bir çalgıdır; icracı komalı aralıkları kulağıyla ve parmak konumuyla bulur.'),
  ('Tanburda sap üzerindeki bağların (perdelerin) varlığı, ud ile kıyaslandığında icracıya hangi sonucu doğurur?', 'Perde yerleri daha sabit olduğundan aralıkları bulmak kolaylaşır', ['Aralıklar hep Batı tonlarına uyacağı için ses kontrolü daha da zorlaşır', 'Çalgıyı yayla çalmak zorunlu olacağı için teknik güçleşir', 'Mandalla ses değiştirmek mümkün olacağından tekniğe gerek kalmaz'], 'Tanburun bağları perde yerlerini belirginleştirir; ud perdesiz olduğundan icracının kulağına daha çok bağımlıdır.'),
  ('Aşağıdaki çalgılardan hangisi hem telli hem de tel grubuna mızrapla vurularak ya da çekilerek çalınan çalgılar arasında yer alır?', 'Ud', ['Ney', 'Kudüm', 'Klasik kemençe'], 'Ud, mızrapla çalınan telli bir çalgıdır; kemençe yayla, ney üfleyerek, kudüm vurarak çalınır.'),
  ('Ney çalan kişiye neyzen, kudüm çalana kudümzen denir. Bu adlandırma hangi dilbilgisel özelliğe dayanır?', 'Çalgı adına Farsça \'-zen\' ekinin getirilmesine', ['Çalgı adının tersten okunarak türetilmiş bir ünvan oluşturulmasına', 'Türkçe \'-cı\' ekinin çalgı adlarına eklenmesi kuralına', 'Çalgı adının hece sayısı azaltılarak kısaltılmasına'], '\'-zen\' eki Farsçada \'çalan, vuran\' anlamı katar; çalgı adına eklenerek icracıyı belirtir.'),
  ('Aşağıdaki çalgı-icracı eşleştirmelerinden hangisi yanlıştır?', 'Kanun - kemani', ['Ud - udi', 'Tanbur - tanburi', 'Kanun - kanuni'], 'Kemani keman çalan kişidir; kanun çalan kişiye kanuni denir.'),
  ('Bir topluluk klasik bir fasıl için hanende, ud, kanun, keman ve kudüm bulmuştur. Eksik olan ve geleneksel heyette sık bulunan üflemeli çalgı hangisidir?', 'Ney', ['Zurna', 'Mey', 'Blok flüt'], 'Fasıl heyetinde telli ve yaylı çalgılara eşlik eden üflemeli çalgı olarak ney bulunur.'),
  ('Kanunun mızrapları icracı tarafından nasıl kullanılır?', 'Sağ ve sol elin işaret parmaklarına takılarak', ['Ağızla tutulup dilin hareketiyle tellere çarptırılarak', 'Bir tahta çubukla tellere vurulacak biçimde elde tutularak', 'Sap boyunca kaydırılarak sesin uzatılmasıyla'], 'Kanuni mızrapları iki elinin işaret parmaklarına takar ve telleri çekerek çalar.'),
  ('Santur ile kanun arasındaki ses üretme farkı nedir?', 'Santurda tellere tokmakla vurulur, kanunda mızrapla çekilir', ['Santur yayla, kanun ise nefesle çalınır; ikisi de tek sesli çalgıdır', 'Santur perdeli bir çalgı, kanun ise tamamen perdesiz bir çalgıdır', 'Santur yalnız süs çalgısı olup kanun ise ana çalgı olarak kullanılır'], 'Santur, ince tokmaklarla tellere vurularak çalınan bir çalgıdır; kanun parmaklara takılan mızraplarla çalınır.'),
  ('Bir kemençeci, ud icracısına göre hangi avantaja sahiptir?', 'Sesi yayla uzatabilmesi ve notayı sürdürebilmesi', ['Mızrapla daha kuvvetli ve sert bir ses çıkarabilmesi, tellere vuruş gücüyle', 'Mandal sayesinde tek hamlede makam değiştirebilmesi, çalgıyı durdurarak', 'Perdelerin hazır olması sayesinde komaları kolayca bulabilmesi'], 'Yaylı çalgı olduğundan kemençe sesi uzun tutabilir ve ses geçişlerini kesintisiz yapabilir; ud mızrapla çalındığı için ses çabuk sönümlenir.'),
  ('Neyzen, kanuni, kemani ve kudümzen bir fasıl heyetinde bir araya gelirse hangi çalgı sınıfları birlikte yer almış olur?', 'Üflemeli, telli, yaylı ve vurmalı çalgılar', ['Yalnız tellerle çalınan çalgılar, yani sadece telli çalgı sınıfı', 'Yalnız ritim tutan ve vurularak çalınan çalgılar, vurmalı çalgı sınıfı', 'Yalnız yayla çalınan çalgılar, yani sadece yaylı çalgı sınıfı'], 'Ney üflemeli, kanun telli, keman yaylı, kudüm vurmalıdır; heyet dört sınıfı birden içerir.'),
  ('Bir makam eserde durak perdesinin altından başlayıp önce güçlü perdeye doğru yükseliyor, sonra durağa iniyorsa bu makamın seyri nasıl adlandırılır?', 'Çıkıcı-inici seyir', ['Yalnız inici seyir', 'Yalnız çıkıcı seyir', 'Usulsüz seyir'], 'Önce yükselip güçlüde dolaşan, sonra durağa inen seyir çıkıcı-inici seyirdir.'),
  ('Bir makamdaki eserin ezgisinde \'çeşni\' denen küçük bölümler neye benzer?', 'Başka bir makamın kısa bir parçasını geçici olarak göstermeye', ['Usulün bir zamanını ayrı bir ezgiyle zenginleştirmeye ve süslemeye', 'Güftenin bir mısrasını ayrı bir makamda okumaya', 'Çalgının bir telini ayrı olarak seslendirmeye'], 'Çeşni, bir makamın karakteristik dizi parçasını ya da cinsini başka bir makam içinde duyurmaya yarar.'),
  ('Bir bestekâr \'Hicaz çeşnisi\' kullanıyorsa bu, eserde neyin duyulduğu anlamına gelir?', 'Hicaz makamının karakteristik dörtlü ya da beşlisinin kısa süre kullanıldığı', ['Eserin tümünün Hicaz perdesinde bittiği ve eserin Hicaz makamında bestelendiği', 'Usulün adının Hicaz olduğu ve vuruşların buna göre dizildiği', 'Güftenin Hicaz adlı bir yöre ve kentten alınmış olduğu'], 'Çeşni, bir makamın tipik sesi (cinsi) başka bir makam içinde kısa süreliğine duyurulduğunda ortaya çıkar.'),
  ('Aynı makamdaki iki eserden birinin sonunda tam karar, diğerinin ortasında asma karar yapılıyor. Dinleyici bu farkı nasıl algılar?', 'İlkinde eserin bittiğini, ikincisinde devam edeceğini', ['İlkinde usulün değiştiğini, ikincisinde hızın arttığını', 'İkincisinde makamın değiştiğini, ilkinde ise güçlünün kaybolduğunu', 'İkisinde de aynı kapanış hissini ve aynı beklentiyi'], 'Tam karar kapanış hissi verir; asma karar ise ezginin devam edeceği beklentisini yaratır.'),
  ('Bir çalgıcı, aynı eseri bir sanatçının sesine uydurmak için bütün sesleri aynı oranda tizleştiriyor. Bu işlem hangi kavramla anlatılır?', 'Ahenk değiştirme', ['Geçki', 'Terkip', 'Seyir'], 'Eserin makam ilişkilerini koruyarak daha pes ya da tiz bir ses başlangıcına taşınması ahenk değiştirme olarak anılır.'),
  ('Basit bir makam ile bileşik bir makam karşılaştırıldığında, bileşik makamın dizisi için hangisi doğrudur?', 'Birden fazla makamın özelliklerini bir arada taşır', ['Tek dörtlü ve tek beşliden oluşur, başka makamla ilişkisi bulunmaz', 'Her zaman dügâhta karar verir ve seyri hep inicidir', 'Seyri mutlaka çıkıcıdır ve tek bir cins kullanır'], 'Bileşik makamlarda iki ya da daha fazla makamın dörtlü ve beşlileri bir arada kullanılır.'),
  ('Aynı duraktan karar veren iki makamı ayırt etmek için hangi ölçüt tek başına yeterli değildir?', 'Yalnız durak perdesine bakmak', ['Dizinin yapısına bakmak', 'Seyri incelemek', 'Güçlü perdeyi bulmak'], 'Aynı perdede karar veren birçok makam bulunur; ayırt etmek için dizi, güçlü ve seyir de incelenir.'),
  ('Bir eser Hicaz makamında başlayıp ortada Uşşak makamına geçiyor, sonra Hicaz\'a dönüyor. Bu eserin yapısı hakkında hangisi doğrudur?', 'Ana makam Hicaz\'dır, Uşşak geçkidir', ['Ana makam Uşşak\'tır', 'Eser iki ayrı fasıldır', 'Eser makamsızdır'], 'Eserin başlayıp bittiği makam ana makamdır; ortadaki Uşşak bölümü geçkidir.'),
  ('Bir bestekâr çıkıcı bir makamda eser besteleyecektir. Hangi yol bu seyri en iyi yansıtır?', 'Durağa yakın pes perdelerden başlayıp güçlüye ve tize doğru ilerlemek', ['Tiz perdelerden başlayıp durağa doğru inerek eseri durak çevresinde bitirmek', 'Yalnız durak perdesinde dolaşarak başka perdeye hiç çıkmamak', 'Usul vuruşlarıyla yön değiştirerek ezgiyi sürekli tekrarlamak'], 'Çıkıcı seyirde ezgi durak çevresinden başlar, güçlüye ve tiz bölgeye yükselir.'),
  ('İnici-çıkıcı seyir izleyen bir makamda eserin başlangıç bölgesi hangisidir?', 'Tiz bölge', ['Pes bölge', 'Durak çevresi', 'Yeden perdesi'], 'İnici-çıkıcı seyirde ezgi tiz bölgeden başlar, durağa iner, sonra tekrar yükselebilir.'),
  ('Bir müzik tarihçisi, bir bestenin 17. yüzyılda yazıldığı iddiasını sınamak için hangi ölçütü kullanabilir?', 'Eserin bu dönemde yazılmış bir derlemede ya da el yazmasında yer alıp almadığına bakmak', ['Eserin bugün ne kadar sevildiğine ve ne sıklıkla çalındığına bakmak', 'Eserin sözlerinin kaç hece olduğunu ve vezne uyup uymadığını saymak', 'Eseri çalan sanatçıların sayısını ve konserlerdeki yerini belirlemek'], 'Tarihlendirmede çağdaş yazılı kaynaklar (mecmua, derleme, el yazması) en güvenilir kanıtlardandır.'),
  ('Bir hanende, hocasından öğrendiği şarkıyı notaya bakmadan okuyor ve her seferinde küçük süslemeler ekliyor. Bu durum meşk geleneğinin hangi özelliğini gösterir?', 'Eserin ezgisi kadar yorumunun da kişiden kişiye aktarıldığını', ['Eserin yazıya geçmeden kısa sürede unutulduğunu ve yorumun önemsiz olduğunu', 'Süslemelerin yasak olduğunu ve eserin birebir aynı çalınması gerektiğini', 'Eserin yalnız tek bir kopyası bulunduğunu ve çoğaltılamadığını'], 'Meşk, ezgiyi tavır ve süslemeleriyle birlikte öğretmen-öğrenci ilişkisi içinde aktarma yöntemidir.'),
  ('Bir öğretmen, öğrencilerine aynı şarkıyı hem Rast hem de Uşşak makamında seslendiriyor ve \'ezgi bir, renk farklı\' diyor. Bu anlatımla öğrencilere en çok neyi göstermek istemiş olabilir?', 'Makamın, aynı ezginin duygusal rengini değiştirebildiğini', ['Usulün makamdan bağımsız seçilebildiğini', 'Şarkının hiçbir biçimde yazıya geçirilemeyeceğini', 'Bütün makamların aralık bakımından tıpatıp aynı olduğunu'], 'Aynı ezgi farklı dizilere taşındığında aralıklar değiştiği için duygusal renk de değişir.'),
  ('Bir müzik topluluğu klasik bir eseri Batı müziğindeki gibi eşit aralıklı bir piyano eşliğinde seslendirmek istiyor. Eser Türk müziği makamında bestelenmişse en büyük zorluk ne olur?', 'Komalı perdelerin piyanoda hazır bulunmaması', ['Usulün piyanoda hiç çalınamaması ve vuruşların duyulmaması', 'Güftenin piyano eşliğinde söylenememesi', 'Makamın adının piyanoda otomatik olarak değişmesi'], 'Piyanonun perdeleri sabit ve eşit aralıklıdır; Türk müziğinin koma düzeyindeki ince aralıkları tam verilemez.'),
  ('Bir gazino orkestrası, bir şarkıyı farklı bir ahenge (daha pes ya da tiz bir başlangıca) taşıyor. Bu değişiklik makamın hangi özelliğini bozmaz?', 'Aralık ilişkilerini', ['Perdelerin mutlak yüksekliğini', 'Eserin tizliğini', 'Sesin tınısını'], 'Ahenk değişince tüm sesler aynı oranda kayar; aralık ilişkileri korunduğundan makam değişmez.'),
  ('Bir hanendenin güftesini yanlış hecelemesi ve vurguyu usulün zayıf zamanına koyması, bestenin hangi yönünü zedeler?', 'Prozodi', ['Makamın durağı', 'Eserin adı', 'Çalgıların sayısı'], 'Sözcüklerin doğal vurgusu ile ezginin vurgusu uyuşmadığında prozodi hatası ortaya çıkar.'),
  ('Bir şarkıdaki \'zemin\' bölümü ile \'meyan\' bölümünü karşılaştıran bir müzikolog aralarında hangi ayrımı yapar?', 'Meyan çoğunlukla daha tiz bölgede dolaşır ve zeminden ezgi olarak ayrılır', ['Meyan usulsüz, zemin usulludur; ikisi farklı usullerle yazılır', 'Zemin sözsüz, meyan sözlüdür; ikisi arasında söz farkı vardır', 'Zemin çalgısal, meyan ise yalnız vokal olarak icra edilir'], 'Zemin eserin ana ezgisini kurar; meyan çoğunlukla tizde gezinen, farklı bir ezgi bölümüdür.'),
  ('Bir saz heyeti bir peşrevi icra ediyor. Heyetin bu eseri okurken \'sözlü eserlerin makamını hazırlamak\' gibi bir görev üstlenmesi hangi özelliğine bağlıdır?', 'Fasılda ilk çalınan, makamı tanıtan eser olmasına', ['Çok kısa olması ve her zaman 3 zamanlı bir usulle yazılması', 'Sözlerinin Farsça olması ve dinî içerikli güftelerden oluşması', 'Eserin yalnız solo ney ile çalınması ve usulsüz olması'], 'Peşrev, fasılda sözlü eserlerden önce çalınır ve fasılın makam havasını ortaya koyar.'),
  ('Bir şarkı güftesinde dört mısra bulunuyor ve bestekâr her mısraya ayrı bir ezgi yazıyor. Hangi şarkı bölümleri bu ezgilerle birebir örtüşür?', 'Zemin, nakarat, meyan ve tekrar nakarat', ['Teslim, hane, zemin ve terennüm; bir peşrevin bölümleriyle birebir', 'Peşrev, kâr, beste ve semai; bir faslın eserleriyle birebir', 'Selam, ayin, na\'t ve taksim; bir ayinin bölümleriyle birebir'], 'Dört mısralı bir şarkıda ezgi sırasıyla zemin, nakarat, meyan ve yeniden nakarat bölümlerine dağılır.'),
  ('Bir kayıtta sanatçı eseri notada yazılandan farklı yavaşlıkta okuyor. Bu durum için en uygun açıklama hangisidir?', 'Tempo, yorumcunun tercihine göre değişebilen bir unsurdur', ['Usulün bilinmemesi nedeniyle hızın hiç belirlenemeyeceği gerçeği', 'Eserin kesin biçimde bozulmuş ve yanlış yazılmış olduğu sonucu', 'Güftenin okunuş hızının eserin makamını belirlediği ilkesi'], 'Usul zaman sayısını verir ama hızı kesin belirlemez; tempo icracının yorumuna bırakılabilir.'),
  ('Bir plak kaydında yalnız taksim yapıldığı bilinen bir tanburinin kaydı, günümüzde neden kıymetli kabul edilir?', 'Tavır ve süsleme gibi notaya geçmeyen icra özelliklerini belgelediği için', ['Notasız olduğu için tek kaynak olması ve başka belge bulunmaması', 'Eserin sözlerini ayrıntılı biçimde içermesi ve söz kaynağı olması', 'Yalnız tarihî bir eşya sayıldığı için müzede korunması gerektiği'], 'Ses kayıtları, notaya tam geçmeyen yorum özelliklerini belgeler ve tarihsel icrayı incelemeye imkân verir.'),
  ('Bir araştırmacı, bir bestekârın eserlerinin çoğunun kısa ve sözlü olduğunu görüyor. Bu bestekâr hangi yüzyıl eğiliminin içindedir?', 'Hafif formlara, özellikle şarkıya yönelen 19. yüzyıl ve sonrası eğiliminin', ['Yalnız ayin besteleyen ve uzun formlara bağlı kalan 17. yüzyıl eğiliminin', 'Yalnız taksimle uğraşıp hiç eser bestelemeyen bir eğilimin', 'Yalnız çalgı bestelemeyi seçen ve sözlü formlardan kaçınan bir eğilimin'], '19. yüzyılda ve sonrasında şarkı gibi kısa ve hafif formlar yaygınlaşmıştır.'),
  ('Bir plak şirketinin 20. yüzyıl başında İstanbul\'da kayıt yapması, Türk müziğinin aktarım biçiminde neyi değiştirmiştir?', 'Meşk dışında eserleri ve icra tarzlarını dinleyerek öğrenme yolunu açmıştır', ['Meşk geleneğini tamamen bitirmiş ve hocasız öğrenmeyi zorunlu kılmıştır', 'Nota yazımını ortadan kaldırmış ve yalnız ses kaydını yaygınlaştırmıştır', 'Eserlerin makamlarını değiştirmiş ve usulleri sadeleştirmiştir'], 'Plaklar, dinleyerek öğrenmeyi yaygınlaştırdı; meşk tümüyle ortadan kalkmadı, yanına yeni bir kanal eklendi.'),
  ('Bir öğrenci \'Notanın icat edilmesiyle meşk gereksiz hâle gelmiştir\' diyor. Bu görüş hangi gerekçeyle eleştirilebilir?', 'Notanın tavır ve süslemeyi tam yansıtamamasıyla', ['Notanın hiç yazılamamasıyla ve ezgiyi göstermekten tamamen yoksun olmasıyla', 'Meşkin yalnız şiir öğretmesi ve ezgiyle ilgisi bulunmamasıyla', 'Meşkin tek sesli olması ve notanın çok sesli olmasıyla'], 'Nota ezgiyi büyük ölçüde kaydeder ama tavır, süsleme gibi yorum özellikleri meşkle öğrenilir.'),
  ('Bir bestecinin eserlerini \'bestelerden çok taksimleriyle\' tanıtan bir biyografi yazarı, o sanatçıyı en çok hangi yönüyle öne çıkarıyor?', 'Doğaçlama icrasındaki ustalığıyla', ['Güfte yazarlığıyla ve şiirlerinin bestelenmesiyle', 'Usul tutmadaki becerisi ve vurmalı çalgıları kullanışıyla', 'Nota yazım yeteneği ve yeni notalama sistemleri geliştirmesiyle'], 'Taksim doğaçlamadır; taksimleriyle tanınan sanatçı doğaçlama icra ustalığıyla öne çıkar.'),
  ('Bir sanatçının hem saray hem tekke çevresinde yetişmiş olması, eserlerinde hangi sonuca yol açabilir?', 'Dinî ve dindışı formlarda eser verebilmesine', ['Yalnız çalgı müziği bestelemesine ve söz kullanmamasına', 'Hiç makam kullanamamasına ve serbest ezgilerle yetinmesine', 'Yalnız tek bir usulde yazmasına ve çeşitliliği kaçırmasına'], 'İki çevrede de yetişen müzisyenler, hem ayin ve ilahi gibi dinî hem de kâr, şarkı gibi dindışı formlarda eser verebilmiştir.'),
  ('Mevlana\'nın doğumunun 800. yıldönümü, 1207 doğum yılı esas alındığında hangi yıla denk gelir?', '2007', ['10035', '2000', '2017'], '1207 + 800 = 2007; bu yıl anma etkinlikleriyle \'Mevlana Yılı\' olarak kutlanmıştır.'),
  ('Mevlevi tarikatının, Mevlana\'nın ölümünden sonra kuruluşunu tamamlayan ve örgütleyen kişi kimdir?', 'Sultan Veled', ['Hüsameddin Çelebi', 'Şems-i Tebrizi', 'Yunus Emre'], 'Mevlana\'nın oğlu Sultan Veled, babasının öğretisine dayanan tarikatın örgütlenmesini sağlamıştır.'),
  ('Mevlana\'nın hayatında dönüm noktası sayılan ve onun şiire ve sema\'ya yönelmesinde etkili olan derviş kimdir?', 'Şems-i Tebrizi', ['Hacı Bektaş Veli', 'Ahmed Yesevi', 'Sadreddin Konevi'], 'Mevlana, Konya\'da Şems-i Tebrizi ile tanışmasından sonra derin bir manevi dönüşüm geçirmiştir.'),
  ('Mevlevi tarikatında \'dede\' unvanını alabilmek için dervişin tamamlaması gereken çile süresi kaç gündür?', '1001', ['10010', '99', '365'], 'Mevlevi adayı mutfakta hizmet ve çilehanede 1001 gün çile çıkarır; ardından dede unvanını alır.'),
  ('Mevlana\'nın Farsça yazdığı ve yaklaşık 25.000 beyitten oluşan büyük eserinin kaç ciltten (defterden) oluştuğu bilinir?', '6', ['3', '4', '12'], 'Mesnevi altı defterden oluşur; ilk 18 beyti \'Dinle neyden\' diye başlar.'),
  ('Mevlevi semazenlerinin başlarındaki sikke ile üstlerindeki beyaz tennurenin simgesel anlamları hangi seçenekte doğru eşleştirilmiştir?', 'Sikke mezar taşını, beyaz tennure kefeni simgeler', ['Sikke kefeni, beyaz tennure mezar taşını simgeler', 'Sikke güneşi, tennure ayı simgeler', 'Sikke şeyhi, tennure müridi simgeler'], 'Geleneksel yoruma göre sikke mezar taşı, beyaz tennure kefen, kara hırka ise kabir simgesidir.'),
  ('Sema sırasında semazenin sağ elini yukarı, sol elini aşağı doğru tutması hangi anlamla açıklanır?', 'Hak\'tan alınanı halka ulaştırmakla', ['Dönüşü hızlandırmakla', 'Dengeyi korumakla', 'Ayini bitirmekle'], 'Sağ el göğe açık, sol el yere dönük olarak Allah\'tan alınan feyzin insanlara aktarılmasını simgeler.'),
  ('Kara hırkanın Mevlevi töreninde semazenlerce sema başlamadan çıkarılması neyi simgeler?', 'Nefsin ve dünya bağlarının bırakılmasını', ['Dönüşün yavaşlamasını', 'Töreni sona erdirmeyi', 'Şeyhe saygı göstermeyi'], 'Hırka kabir simgesidir; çıkarılması insanın dünyevi bağlardan sıyrılıp hakikate yönelmesini anlatır.'),
  ('Mevlevi ayininde ney taksimi çalınmasının, Mesnevi\'nin hangi bölümünün müziksel karşılığı sayıldığı söylenir?', '\'Dinle neyden\' diye başlayan ilk beyitlerin', ['Son beyitlerin', 'Mesnevi\'nin fihristinin', 'Şems\'in şiirlerinin'], 'Ney, Mesnevi\'nin ilk beyitlerinde ayrılık ve hasreti anlatan simge olduğundan ayinin açılışında yer alır.'),
  ('Mevlevi ayininin sonunda yapılan ve Mevlana\'nın ruhuna okunan dua için hangisi söylenebilir?', 'Fatiha ve dualarla ayin kapatılır', ['Ayin hiç dua yapılmadan biter', 'Bir peşrev çalınarak kapanır', 'Kâr okunarak bitirilir'], 'Mevlevi mukabelesi, dua ve Fatiha okunmasıyla tamamlanır.'),
  ('Hacı Arif Bey 1831\'de doğup 1885\'te ölmüştür. Şevki Bey 1860\'ta doğduğuna göre Hacı Arif Bey\'in ölümünde Şevki Bey kaç yaşındaydı?', '25', ['20', '29', '100'], '1885 - 1860 = 25.'),
  ('Udi Hrant Kenkulian 1901-1978 yılları arasında yaşamıştır. Bu bilgiye göre hangisi söylenebilir?', '1916\'da henüz çocuk yaştaydı', ['Dede Efendi ile aynı dönemde yaşayıp onunla meşk etmişti', 'Itri ile çağdaş olup aynı sarayda görev yapmıştı', 'III. Selim döneminde saray müzisyenliği yapmıştı'], '1901\'de doğan Hrant, 1916\'da 15 yaşındaydı; Dede Efendi 1846\'da, Itri 1712 civarında ölmüştür.'),
  ('Itri (öl. 1712) ile Dede Efendi (1778-1846) arasında kaç yıllık bir fark vardır (ölüm yılları esas alınır)?', '134', ['1340', '100', '154'], '1846 - 1712 = 134 yıl.'),
  ('Kantemiroğlu (1673-1723) ile Hamparsum (1768-1839) hakkında hangisi doğrudur?', 'Hamparsum, Kantemiroğlu\'nun ölümünden sonra doğmuştur', ['İkisi aynı yıllarda yaşayıp birlikte meşk etmiştir', 'Hamparsum Kantemiroğlu\'ndan yaklaşık elli yıl önce doğmuştur', 'Hamparsum, Kantemiroğlu\'nun doğrudan öğrencisi olarak yetişmiştir'], 'Kantemiroğlu 1723\'te ölmüş, Hamparsum 1768\'de doğmuştur; aralarında 45 yıl vardır.'),
  ('Aşağıdaki sıralama eskiden yeniye doğru hangisidir?', 'Hamparsum, Dede Efendi, Hacı Arif Bey, Zeki Müren', ['Dede Efendi, Hamparsum, Zeki Müren, Hacı Arif Bey sırasıyla', 'Hacı Arif Bey, Hamparsum, Dede Efendi, Zeki Müren sırasıyla', 'Zeki Müren, Hacı Arif Bey, Dede Efendi, Hamparsum sırasıyla'], 'Doğum yılları: Hamparsum 1768, Dede Efendi 1778, Hacı Arif Bey 1831, Zeki Müren 1931.'),
  ('TRT\'nin yasal olarak kurulduğu yıl hangisidir?', '1964', ['19640', '1950', '1971'], 'TRT 1964\'te kurulmuş ve radyo-televizyon yayıncılığını bir çatı altında toplamıştır.'),
  ('Buselik dörtlüsünün aralıkları sırasıyla 9, 4 ve 9 komadır. Üzerine 9 komalık bir tanini eklenirse oluşan beşli kaç komadır?', '31', ['26', '35', '124'], '9 + 4 + 9 = 22; 22 + 9 = 31 koma tam beşlidir.'),
  ('Bir tam dörtlü 22, bir tanini 9 komadır. Birbirine bir tanini ile bağlanmış iki tam dörtlü kaç komalık aralık oluşturur?', '53', ['106', '49', '58'], '22 + 9 + 22 = 53 koma, yani bir oktavdır.'),
  ('Bir Uşşak dörtlüsünde aralıklar 8, 5 ve 9 komadır. İlk iki aralığın toplamı, üçüncü aralıktan kaç koma fazladır?', '4', ['1', '5', '12'], '8 + 5 = 13; 13 - 9 = 4 koma.'),
  ('Bir tanini 9 komadır ve AEU\'da bir tam ton olarak düşünülür. 53 komalık oktav kaç tanini içerir (tam sayı kısmı olarak)?', '5', ['4', '6', '10'], '53 / 9 = 5,88; tam sayı kısmı 5\'tir.'),
  ('Dügâh, segâh ve çargâh adlarındaki \'dü\', \'se\', \'çâr\' Farsça sayıdır. Bu üç sayının sırasıyla karşılığı hangisidir?', '2, 3, 4', ['1, 2, 3 olarak ardışık sayılar', '3, 4, 5 olarak ardışık sayılar', '2, 4, 6 olarak çift sayılar'], 'Dü iki, se üç, çâr dörttür; bu nedenle dügâh ikinci, segâh üçüncü, çargâh dördüncü yerdir.'),
  ('Uşşak makam adındaki \'uşşak\' sözcüğü Arapçada hangi anlama gelir?', 'Âşıklar', ['Hükümdarlar ve devlet büyükleri', 'Yolcular ve gezginler', 'Şairler ve söz ustaları'], 'Uşşak, \'âşık\'ın çoğuludur ve \'âşıklar\' anlamındadır.'),
  ('Nihavend makamının adı İran\'daki hangi yerle ilişkilendirilir?', 'Nihavend (Nahavand) kenti', ['Şiraz kenti ve çevresindeki bahçeler', 'Tebriz kenti ve çevresindeki dağlar', 'Hemedan kenti ve çevresindeki ovalar'], 'Nihavend, İran\'ın Nahavand kentinin adından gelir.'),
  ('Hisar perdesinin adı, Arapça-Farsça kökenli bir sözcük olarak neyi anlatır?', 'Kale', ['Dağ başındaki yüksek tepe', 'Nehir üzerindeki köprü', 'Şehirdeki kalabalık çarşı'], 'Hisar, \'kale\' anlamına gelir; Hisar perdesi ve Hisar makamı bu adı taşır.'),
  ('Gerdaniye perdesinin adındaki \'gerdan\' sözcüğü Farsçada neyi ifade eder?', 'Boyun', ['Bilek, yani kolun el ile birleştiği yer', 'Omuz, yani kolun gövdeye bağlandığı yer', 'Kulak, yani sesi algılayan organ'], 'Gerdan boyun demektir; gerdaniye perdesi ise \'boyunla ilgili\' anlamda yorumlanır.'),
  ('Arapça-Farsça kökenli \'neva\' sözcüğü, Türk müziğinde bir perde adı olarak neyi anlatır?', 'Nağme, ezgi', ['Rüzgâr ve hafif esinti', 'Sessizlik ve derin sükûnet', 'Dilek ve temenni'], 'Neva, ses ve nağme anlamına gelir; bu nedenle bir perde ve makam adı olarak kullanılır.'),
  ('Eviç perdesinin adındaki \'evç\' sözcüğü hangi anlamla ilişkilidir?', 'Zirve, yüksek nokta', ['Alçak yer', 'Kaynak', 'Köy'], 'Evç, \'tepe, yüksek nokta\' demektir; Eviç perdesi bu nedenle bir yükseklik adı taşır.'),
  ('Hümayun makamının adındaki \'hümayun\' sözcüğü hangi anlama gelir?', 'Kutlu, saygın', ['Kederli ve hüzünlü olan', 'Hızlı ve çevik olan', 'Küçük ve ufak olan'], 'Hümayun, \'kutlu, saray ve hükümdarla ilgili, mübarek\' anlamındadır.'),
  ('Acem perdesinin adı, hangi toplulukla ilişkili bir sözcükten türemiştir?', 'Arap olmayanlar, özellikle İranlılar', ['Türkler ve Orta Asya halkları', 'Rumlar ve Yunan adalarında yaşayanlar', 'Kürtler ve dağlık bölge halkları'], 'Acem, Arapçada \'Arap olmayan, çoğunlukla İranlı\' anlamındadır.'),
  ('Bir perdenin üzerine önce küçük mücenneb diyezi (+5 koma), ardından bakiye bemolü (-4 koma) uygulanıyor. Perdenin toplam değişimi kaç koma olur?', '1', ['9', '-1', '12'], '+5 ile -4 toplanınca +1 koma, yani perde 1 koma tizleşir.'),
  ('Büyük mücenneb diyezi 8, koma diyezi 1 komalık tizleştirme yapıyorsa, bir perde önce büyük mücenneb diyezi sonra koma bemolüyle değiştirildiğinde net değişim kaç komadır?', '7', ['9', '-7', '8'], '+8 ile -1 toplanınca +7 koma yükselme olur.'),
  ('Bir bestekâr dügâh perdesini 4 koma tizleştirmek istiyor. Hangi işareti kullanmalıdır?', 'Bakiye diyezi', ['Koma diyezi', 'Büyük mücenneb diyezi', 'Koma bemolü'], 'Dört komalık tizleştirme bakiye diyeziyle yazılır.'),
  ('Bir parçanın donanımında (dizek başı) bulunan işaretin amacı nedir?', 'Eser boyunca geçerli olan perde değişimlerini baştan bildirmek', ['Usulün zaman sayısını göstermek', 'Eserin hızını belirtmek', 'Güftenin sözlerini yazmak'], 'Donanım, makamın perdeleri için gereken diyez ve bemolleri eserin başında topluca belirtir.'),
  ('Bir öğrenci, Hicaz makamında segâh perdesinin \'küçük mücenneb diyezi\' ile gösterilmesi gerektiğini fark ediyor. Bu işaret segâhı kaç koma tizleştirir?', '5', ['4', '8', '12'], 'Küçük mücenneb diyezi bir perdeyi 5 koma tizleştirir.'),
  ('Bir bakiye diyezi ile bir büyük mücenneb diyezi arasındaki fark kaç komadır (8 - 4)?', '4', ['3', '9', '12'], 'Büyük mücenneb 8, bakiye 4 koma değiştirir; fark 4 komadır.'),
  ('Aynı perdeye art arda iki bakiye diyezi uygulanırsa toplam kaç koma tizleşir?', '8', ['4', '5', '16'], 'Her bakiye diyezi 4 koma tizleştirir; iki kez 4 + 4 = 8 koma yükselir.'),
  ('Çargâh perdesinin üzerine konan koma bemolü ile bakiye diyezi birlikte uygulanırsa net değişim kaç komadır?', '3', ['-3', '5', '8'], '-1 + 4 = +3 koma tizleşme olur.'),
  ('Bakiye bemolü, küçük mücenneb bemolü ve büyük mücenneb bemolü işaretlerini pestleştirme miktarına göre küçükten büyüğe sıralayan seçenek hangisidir?', 'Bakiye, küçük mücenneb, büyük mücenneb', ['Büyük mücenneb, bakiye, küçük mücenneb', 'Küçük mücenneb, bakiye, büyük mücenneb', 'Büyük mücenneb, küçük mücenneb, bakiye'], 'Bakiye 4, küçük mücenneb 5, büyük mücenneb 8 koma değiştirir.'),
  ('Arel-Ezgi-Uzdilek sistemi bir oktavı kaç perdeye (ses basamağına) böler?', '24', ['7', '17', '120'], 'AEU sisteminde oktav 24 perdeden oluşur; bu perdeler 53 komalık aralığa dağılır.'),
  ('Bir kuramcı 6 farklı dörtlü ve 4 farklı beşliyi tanımlıyor ve bunları yalnız dörtlü-beşli birleşimi olarak eşleştiriyor. Kuramsal olarak kaç farklı dizi oluşturulabilir?', '24', ['120', '12', '36'], 'Her dörtlü her beşliyle eşleşebileceğinden 6 x 4 = 24 dizi çıkar.'),
  ('Bir şarkıda ezgi durak perdesi çevresinde başlayıp güçlü perdeye ve tize doğru ilerliyor. Bu davranış neden çıkıcı seyre örnek sayılır?', 'Ezgi durağın yakınında başlayıp güçlüye ve tize doğru yükselir', ['Ezgi tizde başlayıp doğrudan durağa iner', 'Ezgi yalnız durak perdesinde dolaşır', 'Ezgi usul değiştirerek ilerler'], 'Çıkıcı seyirde ezgi durak çevresinde başlayıp güçlü perdeye ve tiz bölgeye yükselir.'),
  ('Bir meşk toplantısında hoca, öğrencisine aynı şarkıyı üç kez okutuyor ve süslemeleri tek tek düzeltiyor. Bu öğretim biçiminin notayla öğretimden farkı nedir?', 'İcra özellikleri doğrudan dinlenip taklit edilerek öğrenilir', ['Hiçbir eser öğretilmez', 'Yalnız söz öğretilir', 'Yalnız usul vurulur'], 'Meşkte ezgi, tavır ve süsleme ses yoluyla aktarılır; nota yalnız ezgi iskeletini gösterir.'),
  ('Bir şarkıda zemin 7 ölçü, nakarat da 7 ölçü, meyan 5 ölçüdür. Dört mısralık şarkı zemin, nakarat, meyan ve tekrar nakarat sırasıyla çalınırsa toplam kaç ölçü eder?', '26', ['104', '24', '31'], '7 + 7 + 5 + 7 = 26 ölçüdür.'),
  ('Bir fasılda 1 peşrev, 1 kâr, 1 beste, 1 ağır semai, 1 yürük semai ve 5 şarkı bulunuyor. Sözlü eserlerin sayısı kaçtır?', '9', ['4', '5', '11'], 'Kâr, beste, ağır semai, yürük semai ve 5 şarkı sözlüdür: 4 + 5 = 9 eser.'),
  ('Bir fasılda 2 saz eseri (peşrev ve saz semaisi) ve 8 sözlü eser varsa saz eserlerinin oranı yüzde kaçtır?', '20', ['10', '25', '100'], 'Toplam 10 eserden 2\'si saz eseridir; 2/10 = %20.'),
  ('Bir kâr 4 devir zemin, 3 devir meyan, 2 devir terennüm içeriyor ve her devir 28 zamandır. Eser kaç zamandır?', '252', ['1008', '224', '280'], '4 + 3 + 2 = 9 devir; 9 x 28 = 252 zaman.'),
  ('Bir taksimci Hicaz makamında taksime başlıyor ve sonunda dügâhta duruyor. Bu icra sırasında kudümzenden ne beklenir?', 'Usul vurmaması', ['Devr-i kebir usulünü baştan sona vurması', 'Sofyan usulüyle tempo tutması', 'Düyek usulüyle vuruşları çoğaltması'], 'Taksim usulsüzdür; bu nedenle kudümzen usul vurmaz.'),
  ('Bir bestekâr hane sayısı fazla, bölümleri uzun ve sözsüz bir eser yazıyor. Bu eser fasılda hangi bölümde kullanılmaya en uygundur?', 'Faslın başında, açılış eseri olarak', ['Faslın tam ortasında, kâr olarak', 'Faslın sonunda, şarkı olarak', 'Ayinin sonunda, son selam olarak'], 'Hane sayısı fazla, geniş ve sözsüz eserler peşrevdir; fasılda ilk çalınır.'),
  ('Bir hanende sözlü eserleri ağırdan hafife sıralıyor: kâr, beste, ağır semai, yürük semai. Sıralamayı belirleyen ana ölçüt hangisidir?', 'Eserin ağırlığı ve usul büyüklüğü', ['Güftenin yazılış yılı', 'Çalgıcıların sayısı', 'Besteci adlarının alfabetik sırası'], 'Klasik fasılda sözlü eserler ağır ve büyük usullerden hafif ve küçük usullere doğru sıralanır.'),
];
